pub fn record_lit_instantiated_fields(
    type_name: Option<String>,
    expected: Option<Rc<Node>>,
    scope: Rc<InferScope>,
) -> Option<Rc<Vec<Rc<Node>>>> {
    match type_name.clone() {
        Some(tn) => match expected.clone() {
            Some(exp) => {
                if (type_name_compatible(
                    authored_name_at(scope.type_env.clone().source_indices.clone(), exp.clone()),
                    tn.clone(),
                ) == false)
                {
                    None
                } else {
                    if ((exp.children.clone().len() as i64) == 0) {
                        None
                    } else {
                        match lookup_type_for(scope.type_env.clone(), exp.clone()) {
                            Some(decl) => {
                                if ((decl.params.clone().len() as i64)
                                    != (exp.children.clone().len() as i64))
                                {
                                    None
                                } else {
                                    {
                                        let subst = Rc::new(decl.params.clone().iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned().fold(v1_rt::rc_empty_map::<String, Rc<Node>>(), |acc: Rc<HashMap<String, Rc<Node>>>, pair: (i64, Rc<Node>)| {
                        let slot = authored_name_at(scope.type_env.clone().source_indices.clone(), pair.1.clone());
match exp.children.clone().iter().cloned().skip(pair.0.clone() as usize).next() {
    Some(arg) => v1_rt::rc_map_insert(acc.clone(), slot.clone(), resolved_type(arg.clone())),
    None => acc.clone(),
}
});
                                        let template_fields = decl.children.clone();
                                        Some(Rc::new({
                                            let mut __result = Vec::new();
                                            for sf in template_fields.clone().iter().cloned() {
                                                __result.push(Rc::new(Node {
                                                    name: sf.name.clone(),
                                                    span: sf.span.clone(),
                                                    ident_span: sf.ident_span.clone(),
                                                    children: sf.children.clone(),
                                                    connective: sf.connective.clone(),
                                                    params: sf.params.clone(),
                                                    inferred: Some(Rc::new(
                                                        InferredNode::Resolved {
                                                            node: substitute_generics(
                                                                field_node_type_expr(sf.clone()),
                                                                subst.clone(),
                                                                scope
                                                                    .type_env
                                                                    .clone()
                                                                    .source_indices
                                                                    .clone(),
                                                            ),
                                                        },
                                                    )),
                                                    return_cardinality: sf
                                                        .return_cardinality
                                                        .clone(),
                                                    uses: sf.uses.clone(),
                                                    body: sf.body.clone(),
                                                    transport: sf.transport.clone(),
                                                    properties: sf.properties.clone(),
                                                    type_annotation: sf.type_annotation.clone(),
                                                    is_self_recursive: sf.is_self_recursive.clone(),
                                                    has_non_tail_self_call: sf
                                                        .has_non_tail_self_call
                                                        .clone(),
                                                    match_pattern: sf.match_pattern.clone(),
                                                    expr_data: sf.expr_data.clone(),
                                                    ident: None,
                                                }));
                                            }
                                            __result
                                        }))
                                    }
                                }
                            }
                            None => None,
                        }
                    }
                }
            }
            None => None,
        },
        None => None,
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct KernelListTyDiag {
    pub ty: Rc<Node>,
    pub miss_diags: Rc<Vec<Rc<ErrorNode>>>,
}

pub fn list_kernel_ty_from_element(element: Rc<Node>) -> Rc<KernelListTyDiag> {
    {
        let b = make_container_type("List".to_string(), element.clone());
        Rc::new(KernelListTyDiag {
            ty: b.ty.clone(),
            miss_diags: b.diagnostics.clone(),
        })
    }
}

pub fn set_kernel_ty_from_element(element: Rc<Node>) -> Rc<KernelListTyDiag> {
    {
        let b = make_container_type("Set".to_string(), element.clone());
        Rc::new(KernelListTyDiag {
            ty: b.ty.clone(),
            miss_diags: b.diagnostics.clone(),
        })
    }
}

pub fn set_builtin_receiver_is_set(receiver_arg: Rc<Node>, scope: Rc<InferScope>) -> bool {
    match arg_value(receiver_arg.clone())
        .inferred
        .clone()
        .as_deref()
        .cloned()
    {
        Some(InferredNode::Resolved {
            node: receiver_type,
            ..
        }) => node_is_set_collection(
            receiver_type.clone(),
            scope.type_env.clone().source_indices.clone(),
        ),
        _ => false,
    }
}

pub fn set_union_other_operand_is_resolved_non_set(
    other_arg: Rc<Node>,
    scope: Rc<InferScope>,
) -> bool {
    match arg_value(other_arg.clone())
        .inferred
        .clone()
        .as_deref()
        .cloned()
    {
        Some(InferredNode::Resolved {
            node: other_type, ..
        }) => !node_is_set_collection(
            other_type.clone(),
            scope.type_env.clone().source_indices.clone(),
        ),
        _ => false,
    }
}

pub fn set_element_type_from_receiver(
    receiver_type: Rc<Node>,
    scope: Rc<InferScope>,
) -> Option<Rc<Node>> {
    match set_element_type_in_env(receiver_type.clone(), scope.type_env.clone()) {
        Some(elem_slot) => Some(child_type_node(elem_slot.clone())),
        None => None,
    }
}

pub fn set_element_type_is_concrete(elem: Rc<Node>) -> bool {
    match elem.inferred.clone() {
        Some(inf) => !is_type_variable(inf.clone()),
        None => true,
    }
}

pub fn set_element_types_mismatch(
    recv_elem: Rc<Node>,
    operand_elem: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    ((set_element_type_is_concrete(recv_elem.clone())
        && set_element_type_is_concrete(operand_elem.clone()))
        && !node_type_compatible(
            recv_elem.clone(),
            operand_elem.clone(),
            source_indices.clone(),
        ))
}

pub fn type_node_is_callable(n: Rc<Node>) -> bool {
    ((n.params.clone().len() as i64) > 0)
}

pub fn brand_grounds_transparently_to(
    name: String,
    other: Rc<Node>,
    type_env: Rc<TypeEnv>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    match lookup_type_by_name(type_env.clone(), name.clone()) {
        Some(resolved) => {
            ((((resolved.connective.clone() == Connective::NoConnective)
                && ((resolved.children.clone().len() as i64) == 0))
                && (resolved.inferred.clone() != None))
                && match resolved.inferred.clone().as_deref().cloned() {
                    Some(InferredNode::Resolved { node: target, .. }) => {
                        let target_name = authored_name_at(source_indices.clone(), target.clone());
                        let other_name = authored_name_at(source_indices.clone(), other.clone());
                        ((is_kernel_type(target_name.clone())
                            && (target_name.clone() == other_name.clone()))
                            || (qualified_last_segment(target_name.clone())
                                == qualified_last_segment(other_name.clone())))
                    }
                    _ => false,
                })
        }
        None => false,
    }
}

pub fn nominal_call_arg_brand_mismatch(
    formal: Rc<Node>,
    actual: Rc<Node>,
    type_env: Rc<TypeEnv>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let formal_name = authored_name_at(source_indices.clone(), formal.clone());
        let actual_name = authored_name_at(source_indices.clone(), actual.clone());
        (((((((((((formal.connective.clone() != Connective::Arrow)
            && (actual.connective.clone() != Connective::Arrow))
            && (formal_name.clone() != "".to_string()))
            && (actual_name.clone() != "".to_string()))
            && (qualified_last_segment(formal_name.clone())
                != qualified_last_segment(actual_name.clone())))
            && (structural_carrier_template_name(formal.clone(), source_indices.clone())
                == structural_carrier_template_name(actual.clone(), source_indices.clone())))
            && !is_declared_container_alias_spelling(formal_name.clone()))
            && !is_declared_container_alias_spelling(actual_name.clone()))
            && !brand_grounds_transparently_to(
                formal_name.clone(),
                actual.clone(),
                type_env.clone(),
                source_indices.clone(),
            ))
            && !brand_grounds_transparently_to(
                actual_name.clone(),
                formal.clone(),
                type_env.clone(),
                source_indices.clone(),
            ))
            && !transparent_alias_identity_agrees(
                type_env.symbol_index.clone(),
                formal_name.clone(),
                actual_name.clone(),
            ))
    }
}

pub fn is_where_refinement_type(ty: Rc<Node>) -> bool {
    (((ty.connective.clone() == Connective::Conj) && (ty.type_annotation.clone() != None))
        && ((ty.children.clone().len() as i64) == 1))
}

pub fn where_refinement_chain(ty: Rc<Node>, type_env: Rc<TypeEnv>) -> Rc<Vec<Rc<Node>>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if is_where_refinement_type(ty.clone()) {
            match ty.children.clone().first().cloned() {
                Some(base) => {
                    let base_resolved = match lookup_type_for(type_env.clone(), base.clone()) {
                        Some(resolved) => resolved.clone(),
                        None => base.clone(),
                    };
                    v1_rt::concat(
                        Rc::new(vec![ty.clone()]),
                        where_refinement_chain(base_resolved.clone(), type_env.clone()),
                    )
                }
                None => Rc::new(vec![ty.clone()]),
            }
        } else {
            Rc::new(vec![ty.clone()])
        }
    })
}

pub fn type_expr_where_refinement_predicates(ty: Rc<Node>) -> Rc<Vec<Rc<Node>>> {
    if is_where_refinement_type(ty.clone()) {
        match ty.type_annotation.clone() {
            Some(annot) => match annot.connective.clone() {
                Connective::Conj => annot.children.clone(),
                _ => Rc::new(vec![annot.clone()]),
            },
            None => Rc::new(vec![]),
        }
    } else {
        Rc::new(vec![])
    }
}

pub fn type_where_refinement_predicates_transitive(
    ty: Rc<Node>,
    type_env: Rc<TypeEnv>,
) -> Rc<Vec<Rc<Node>>> {
    Rc::new({
        let mut __result = Vec::new();
        for link in where_refinement_chain(ty.clone(), type_env.clone())
            .iter()
            .cloned()
        {
            __result.extend(
                (*type_expr_where_refinement_predicates(link.clone()))
                    .iter()
                    .cloned(),
            );
        }
        __result
    })
}

pub fn peel_where_refinement_base(ty: Rc<Node>, type_env: Rc<TypeEnv>) -> Rc<Node> {
    match where_refinement_chain(ty.clone(), type_env.clone())
        .last()
        .cloned()
    {
        Some(ground) => ground.clone(),
        None => ty.clone(),
    }
}

pub fn where_predicate_name_at(
    pred: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    field_init_node_name_at(pred.clone(), source_indices.clone())
}

pub fn where_predicate_named_int_arg(
    pred: Rc<Node>,
    field: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<i64> {
    match record_lit_named_field_value_optional(
        field_init_node_value(pred.clone()),
        field.clone(),
        source_indices.clone(),
    ) {
        Some(field_expr) => expr_literal_int_optional(field_expr.clone()),
        None => None,
    }
}

pub fn where_predicate_canonical_name(pred_name: String) -> String {
    if (pred_name.clone() == "brand".to_string()) {
        "Brand".to_string()
    } else {
        pred_name.clone()
    }
}

pub fn where_predicate_optional_int_args_match(
    left: Rc<Node>,
    right: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let min_ok = where_predicate_int_bound_args_equivalent(
            left.clone(),
            right.clone(),
            "min".to_string(),
            source_indices.clone(),
        );
        let max_ok = where_predicate_int_bound_args_equivalent(
            left.clone(),
            right.clone(),
            "max".to_string(),
            source_indices.clone(),
        );
        (min_ok.clone() && max_ok.clone())
    }
}

pub fn where_predicate_int_bound_args_equivalent(
    left: Rc<Node>,
    right: Rc<Node>,
    field: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    match record_lit_named_field_value_optional(
        field_init_node_value(left.clone()),
        field.clone(),
        source_indices.clone(),
    ) {
        None => match record_lit_named_field_value_optional(
            field_init_node_value(right.clone()),
            field.clone(),
            source_indices.clone(),
        ) {
            None => true,
            Some(_) => false,
        },
        Some(left_expr) => match record_lit_named_field_value_optional(
            field_init_node_value(right.clone()),
            field.clone(),
            source_indices.clone(),
        ) {
            None => false,
            Some(right_expr) => match expr_literal_int_optional(left_expr.clone()) {
                Some(a) => match expr_literal_int_optional(right_expr.clone()) {
                    Some(b) => (a.clone() == b.clone()),
                    None => false,
                },
                None => false,
            },
        },
    }
}

pub fn where_predicate_literal_string_args_match(left: Rc<Node>, right: Rc<Node>) -> bool {
    match expr_literal_string_optional(field_init_node_value(left.clone())) {
        Some(a) => match expr_literal_string_optional(field_init_node_value(right.clone())) {
            Some(b) => (a.clone() == b.clone()),
            None => false,
        },
        None => match expr_literal_string_optional(field_init_node_value(right.clone())) {
            Some(_) => false,
            None => true,
        },
    }
}

pub fn where_refinement_predicates_equivalent(
    formal_pred: Rc<Node>,
    actual_pred: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let formal_name = where_predicate_canonical_name(where_predicate_name_at(
            formal_pred.clone(),
            source_indices.clone(),
        ));
        let actual_name = where_predicate_canonical_name(where_predicate_name_at(
            actual_pred.clone(),
            source_indices.clone(),
        ));
        if (formal_name.clone() != actual_name.clone()) {
            false
        } else {
            if (formal_name.clone() == "range".to_string()) {
                where_predicate_optional_int_args_match(
                    formal_pred.clone(),
                    actual_pred.clone(),
                    source_indices.clone(),
                )
            } else {
                if (((((formal_name.clone() == "Brand".to_string())
                    || (formal_name.clone() == "Pattern".to_string()))
                    || (formal_name.clone() == "Format".to_string()))
                    || (formal_name.clone() == "ContentEncoding".to_string()))
                    || (formal_name.clone() == "Domain".to_string()))
                {
                    where_predicate_literal_string_args_match(
                        formal_pred.clone(),
                        actual_pred.clone(),
                    )
                } else {
                    true
                }
            }
        }
    }
}

pub fn where_refinement_min_length_implication_note() -> String {
    thread_local! {
        static CACHED: String = {
            "THE FRAGMENT IS TWO PARTIAL FUNCTIONS, NOT AN IMPLICATION ENGINE, and the asymmetry between them is the entire soundness argument. Predicate implication in general is undecidable, so this decides exactly one relation and refuses outside it: a value whose refinement GUARANTEES a minimum length satisfies a formal position whose refinement DEMANDS a minimum length AND NOTHING ELSE. Provider and demander are separate partial functions over the same closed predicate vocabulary because a predicate can inhabit one side and not the other, and collapsing them into one min-length table is a FAIL-OPEN that the obvious framing walks straight into: model lower_hex_64 as min-length 64 on both sides and a formal lower_hex_64 is then satisfied by an actual lower_hex_128, since 128 >= 64 — but those predicates demand DIFFERENT EXACT LENGTHS and a 128-digit string is not a valid sha256 hex. lower_hex_N therefore appears as a PROVIDER only (it guarantees exactly N lower-hex digits, hence at least N characters) and never as a demander (it demands an exact length and a charset, neither of which a length lower bound establishes). non_empty is the only predicate in the live vocabulary that is a pure length lower bound, so it is the only demander, and it is a provider too because it demands what it guarantees. Everything outside both tables answers Absent and the caller falls through to the pre-existing name-equality path unchanged, so this widens what the wall can DECIDE and narrows nothing it already decided. oci_other_digest_algorithm and oci_other_digest_encoded are deliberately NOT providers even though their grammars happen to exclude the empty string: that fact lives in oci_digest_algorithm_wire_holds / oci_encoded_digest_syntax_valid as a consequence of a syntax walk, not as a declared constant this table could cite, and asserting a bound the predicate does not state is the fabrication DESIGN §5 forbids. The four lower_hex_N bounds ARE declared constants — each is content_hash_validate_lower_hex_length(text, expected_hex_digits: N), whose body is text.length() == N — so the number in this table is the number in the predicate, cited rather than restated. WHY THIS IS A WALL AND NOT A WIDENING: the two corpus sites it closes (std.content_hash serialize_content_hash, `s.digest as NonEmptyStr` over Fnv1a64StructuralDigestHex and `d.hex as NonEmptyStr` over Sha1DigestHex) were carrying WhereRefinementUnenforced advisories for REFUSED evidence, not absent evidence — the value's own declared type already proved the property and where_refinement_predicates_equivalent could not see it because it compares predicate NAMES for equality, and lower_hex_40 != non_empty. WHAT IS NOT STRUCTURAL, STATED AT ITS HONEST RUNG (§4b) BECAUSE A TABLE PAIR WHOSE SOUNDNESS LIVES IN PROSE DECAYS SILENTLY: nothing prevents a predicate from being enrolled in BOTH tables, and membership in both is NOT the fail-open — non_empty is deliberately in both and is sound there, because it demands exactly what it guarantees. The real enrollment condition is narrower: a predicate may take a REQUIRED row only if its entire semantics is a length lower bound and nothing else. lower_hex_64 in both tables would be unsound not because it appears twice but because it demands an exact length and a charset that a lower bound does not establish. That condition is enforced by nobody: these are two hand-written name-keyed partial functions, so a future demander row asserting more than length would fail open and no check would fire. The decided relation guaranteed >= required is mechanically enforced; the authoring discipline that populates the demander table is DILIGENCE, rung MITIGATABLE, and it is contained only by the vocabulary being closed and small. Next-rung trigger is the same dissolve-on below: once the bounds are fields on WhereRefinementPredicateKind's own declaration, a predicate states its guarantee and its demand once and the mis-enrollment has no place to be written. Dissolve-on: feature:where-refinement-predicate-coproduct — when WhereRefinementPredicateKind replaces the string classifiers, the guaranteed and required bounds become fields on the predicate's own declaration rather than two tables a reader must keep in lockstep with where_refinement_is_string_literal_predicate and decidable_where_string_predicate_holds.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn where_predicate_guaranteed_min_length(pred_name: String) -> Option<i64> {
    if (pred_name.clone() == "non_empty".to_string()) {
        Some(1)
    } else {
        if (pred_name.clone() == "lower_hex_16".to_string()) {
            Some(16)
        } else {
            if (pred_name.clone() == "lower_hex_40".to_string()) {
                Some(40)
            } else {
                if (pred_name.clone() == "lower_hex_64".to_string()) {
                    Some(64)
                } else {
                    if (pred_name.clone() == "lower_hex_128".to_string()) {
                        Some(128)
                    } else {
                        None
                    }
                }
            }
        }
    }
}

pub fn where_predicate_required_min_length(pred_name: String) -> Option<i64> {
    if (pred_name.clone() == "non_empty".to_string()) {
        Some(1)
    } else {
        None
    }
}

pub fn where_refinement_predicate_min_length_implies(
    formal_pred: Rc<Node>,
    actual_pred: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    match where_predicate_required_min_length(where_predicate_canonical_name(
        where_predicate_name_at(formal_pred.clone(), source_indices.clone()),
    )) {
        Some(required) => {
            match where_predicate_guaranteed_min_length(where_predicate_canonical_name(
                where_predicate_name_at(actual_pred.clone(), source_indices.clone()),
            )) {
                Some(guaranteed) => (guaranteed.clone() >= required.clone()),
                None => false,
            }
        }
        None => false,
    }
}

pub fn where_refinement_predicate_satisfied_by(
    formal_pred: Rc<Node>,
    actual_pred: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    (where_refinement_predicates_equivalent(
        formal_pred.clone(),
        actual_pred.clone(),
        source_indices.clone(),
    ) || where_refinement_predicate_min_length_implies(
        formal_pred.clone(),
        actual_pred.clone(),
        source_indices.clone(),
    ))
}

pub fn where_refinement_predicates_covered(
    formal_preds: Rc<Vec<Rc<Node>>>,
    actual_preds: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let mut __all = true;
        for fp in formal_preds.clone().iter().cloned() {
            if !({
                let mut __found = false;
                for ap in actual_preds.clone().iter().cloned() {
                    if where_refinement_predicate_satisfied_by(
                        fp.clone(),
                        ap.clone(),
                        source_indices.clone(),
                    ) {
                        __found = true;
                        break;
                    }
                }
                __found
            }) {
                __all = false;
                break;
            }
        }
        __all
    }
}

pub fn decidable_where_int_predicate_holds(
    pred_name: String,
    pred: Rc<Node>,
    value: i64,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<bool> {
    if (pred_name.clone() == "gt_zero".to_string()) {
        Some((value.clone() > 0))
    } else {
        if (pred_name.clone() == "range".to_string()) {
            {
                let passes_min = match record_lit_named_field_value_optional(
                    field_init_node_value(pred.clone()),
                    "min".to_string(),
                    source_indices.clone(),
                ) {
                    None => Some(true),
                    Some(field_expr) => match expr_literal_int_optional(field_expr.clone()) {
                        Some(lo) => Some((value.clone() >= lo.clone())),
                        None => None,
                    },
                };
                let passes_max = match record_lit_named_field_value_optional(
                    field_init_node_value(pred.clone()),
                    "max".to_string(),
                    source_indices.clone(),
                ) {
                    None => Some(true),
                    Some(field_expr) => match expr_literal_int_optional(field_expr.clone()) {
                        Some(hi) => Some((value.clone() <= hi.clone())),
                        None => None,
                    },
                };
                match passes_min.clone() {
                    Some(min_ok) => match passes_max.clone() {
                        Some(max_ok) => Some((min_ok.clone() && max_ok.clone())),
                        None => None,
                    },
                    None => None,
                }
            }
        } else {
            None
        }
    }
}

