pub fn decidable_where_string_predicate_holds(pred_name: String, value: String) -> Option<bool> {
    if (pred_name.clone() == "non_empty".to_string()) {
        Some((v1_rt::string_length(&value) > 0))
    } else {
        if (pred_name.clone() == "lower_hex_64".to_string()) {
            Some(content_hash_validate_lower_hex_length(value.clone(), 64))
        } else {
            if (pred_name.clone() == "lower_hex_40".to_string()) {
                Some(content_hash_validate_lower_hex_length(value.clone(), 40))
            } else {
                if (pred_name.clone() == "lower_hex_128".to_string()) {
                    Some(content_hash_validate_lower_hex_length(value.clone(), 128))
                } else {
                    if (pred_name.clone() == "lower_hex_16".to_string()) {
                        Some(content_hash_validate_lower_hex_length(value.clone(), 16))
                    } else {
                        if (pred_name.clone() == "oci_other_digest_algorithm".to_string()) {
                            Some(oci_other_digest_algorithm(value.clone()))
                        } else {
                            if (pred_name.clone() == "oci_other_digest_encoded".to_string()) {
                                Some(oci_other_digest_encoded(value.clone()))
                            } else {
                                None
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn where_predicate_range_non_literal_bound_reason(
    pred: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<String> {
    match record_lit_named_field_value_optional(
        field_init_node_value(pred.clone()),
        "min".to_string(),
        source_indices.clone(),
    ) {
        Some(min_expr) => match expr_literal_int_optional(min_expr.clone()) {
            Some(_) => match record_lit_named_field_value_optional(
                field_init_node_value(pred.clone()),
                "max".to_string(),
                source_indices.clone(),
            ) {
                Some(max_expr) => match expr_literal_int_optional(max_expr.clone()) {
                    Some(_) => None,
                    None => Some("predicate argument is not an int literal".to_string()),
                },
                None => None,
            },
            None => Some("predicate argument is not an int literal".to_string()),
        },
        None => match record_lit_named_field_value_optional(
            field_init_node_value(pred.clone()),
            "max".to_string(),
            source_indices.clone(),
        ) {
            Some(max_expr) => match expr_literal_int_optional(max_expr.clone()) {
                Some(_) => None,
                None => Some("predicate argument is not an int literal".to_string()),
            },
            None => None,
        },
    }
}

pub fn where_refinement_unenforced_error(
    predicate: String,
    formal: Rc<Node>,
    reason: String,
    span: Rc<SourceSpan>,
    module_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<ErrorNode> {
    make_error_node(
        Rc::new(CompilerDiagnostic::WhereRefinementUnenforced {
            predicate: predicate.clone(),
            formal_type: node_type_shape(formal.clone(), source_indices.clone()),
            reason: reason.clone(),
            span: span.clone(),
        }),
        module_name.clone(),
    )
}

pub fn where_refinement_diags_for_predicate(
    pred: Rc<Node>,
    formal: Rc<Node>,
    value_expr: Rc<Node>,
    span: Rc<SourceSpan>,
    module_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    {
        let pname = field_init_node_name_at(pred.clone(), source_indices.clone());
        let refinement_refusal = Rc::new(vec![type_mismatch_error(
            node_type_shape(formal.clone(), source_indices.clone()),
            node_type_shape(resolved_type(value_expr.clone()), source_indices.clone()),
            span.clone(),
            module_name.clone(),
        )]);
        if where_refinement_is_int_literal_predicate(pname.clone()) {
            match expr_literal_int_optional(value_expr.clone()) {
                Some(v) => match decidable_where_int_predicate_holds(
                    pname.clone(),
                    pred.clone(),
                    v.clone(),
                    source_indices.clone(),
                ) {
                    Some(holds) => {
                        if !holds.clone() {
                            refinement_refusal
                        } else {
                            Rc::new(vec![])
                        }
                    }
                    None => {
                        if (pname.clone() == "range".to_string()) {
                            match where_predicate_range_non_literal_bound_reason(
                                pred.clone(),
                                source_indices.clone(),
                            ) {
                                Some(reason) => Rc::new(vec![where_refinement_unenforced_error(
                                    pname.clone(),
                                    formal.clone(),
                                    reason.clone(),
                                    span.clone(),
                                    module_name.clone(),
                                    source_indices.clone(),
                                )]),
                                None => Rc::new(vec![where_refinement_unenforced_error(
                                    pname.clone(),
                                    formal.clone(),
                                    "int predicate not implemented".to_string(),
                                    span.clone(),
                                    module_name.clone(),
                                    source_indices.clone(),
                                )]),
                            }
                        } else {
                            Rc::new(vec![where_refinement_unenforced_error(
                                pname.clone(),
                                formal.clone(),
                                "int predicate not implemented".to_string(),
                                span.clone(),
                                module_name.clone(),
                                source_indices.clone(),
                            )])
                        }
                    }
                },
                None => {
                    if expr_is_any_literal(value_expr.clone()) {
                        refinement_refusal
                    } else {
                        Rc::new(vec![where_refinement_unenforced_error(
                            pname.clone(),
                            formal.clone(),
                            "non-literal value at refined position".to_string(),
                            span.clone(),
                            module_name.clone(),
                            source_indices.clone(),
                        )])
                    }
                }
            }
        } else {
            if where_refinement_is_string_literal_predicate(pname.clone()) {
                {
                    let string_literal_value =
                        match expr_literal_string_optional(value_expr.clone()) {
                            Some(v) => Some(v.clone()),
                            None => expr_literal_symbol_optional(value_expr.clone()),
                        };
                    match string_literal_value.clone() {
                        Some(v) => {
                            match decidable_where_string_predicate_holds(pname.clone(), v.clone()) {
                                Some(holds) => {
                                    if !holds.clone() {
                                        refinement_refusal
                                    } else {
                                        Rc::new(vec![])
                                    }
                                }
                                None => Rc::new(vec![where_refinement_unenforced_error(
                                    pname.clone(),
                                    formal.clone(),
                                    "string predicate not implemented".to_string(),
                                    span.clone(),
                                    module_name.clone(),
                                    source_indices.clone(),
                                )]),
                            }
                        }
                        None => {
                            if expr_is_any_literal(value_expr.clone()) {
                                refinement_refusal
                            } else {
                                Rc::new(vec![where_refinement_unenforced_error(
                                    pname.clone(),
                                    formal.clone(),
                                    "non-literal value at refined position".to_string(),
                                    span.clone(),
                                    module_name.clone(),
                                    source_indices.clone(),
                                )])
                            }
                        }
                    }
                }
            } else {
                if where_refinement_is_deferred_predicate(pname.clone()) {
                    Rc::new(vec![where_refinement_unenforced_error(
                        pname.clone(),
                        formal.clone(),
                        "predicate deferred at compile time".to_string(),
                        span.clone(),
                        module_name.clone(),
                        source_indices.clone(),
                    )])
                } else {
                    Rc::new(vec![where_refinement_unenforced_error(
                        pname.clone(),
                        formal.clone(),
                        "predicate not enforced at compile time".to_string(),
                        span.clone(),
                        module_name.clone(),
                        source_indices.clone(),
                    )])
                }
            }
        }
    }
}

pub fn where_refinement_value_under_cast(mut value_expr: Rc<Node>) -> Rc<Node> {
    loop {
        match (*value_expr.expr_data.clone()).clone() {
            ExprData::ExprCast => {
                let __tco_0 = cast_expr(value_expr);
                value_expr = __tco_0;
                continue;
            }
            _ => {
                break value_expr.clone();
            }
        }
    }
}

pub fn where_refinement_peel_cost_note() -> String {
    thread_local! {
        static CACHED: String = {
            "Cost shape (bare-minimum-cost, DESIGN 6): peel_nominal_alias_identity runs only on the refusal path (predicates present AND not covered), inside the final else of where_refinement_mismatch_diags. That fn runs on EVERY infer_expr with an expected type; 97% of calls find zero predicates, and an eager peel at fn entry was 6.5s of discarded resolve_node_bounded work per host_effect_realize entry compile (typecheck-perf investigation, 2026-07-31). formal_checked is consumed only by where_refinement_diags_for_predicate, so the sink is behavior-identical: peel is pure and its NodeResolveResult diagnostics were already discarded.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn where_refinement_mismatch_diags(
    formal: Rc<Node>,
    value_expr: Rc<Node>,
    span: Rc<SourceSpan>,
    module_name: String,
    type_env: Rc<TypeEnv>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    {
        let source_indices = type_env.source_indices.clone();
        let formal_resolved = match lookup_type_for(type_env.clone(), formal.clone()) {
            Some(resolved) => resolved.clone(),
            None => formal.clone(),
        };
        let preds =
            type_where_refinement_predicates_transitive(formal_resolved.clone(), type_env.clone());
        if ((preds.clone().len() as i64) == 0) {
            Rc::new(vec![])
        } else {
            {
                let value_for_refinement = where_refinement_value_under_cast(value_expr.clone());
                let actual_raw = resolved_type(value_for_refinement.clone());
                let actual_resolved = match lookup_type_for(type_env.clone(), actual_raw.clone()) {
                    Some(resolved) => resolved.clone(),
                    None => actual_raw.clone(),
                };
                let actual_preds = type_where_refinement_predicates_transitive(
                    actual_resolved.clone(),
                    type_env.clone(),
                );
                if where_refinement_predicates_covered(
                    preds.clone(),
                    actual_preds.clone(),
                    source_indices.clone(),
                ) {
                    Rc::new(vec![])
                } else {
                    {
                        let formal_checked = peel_nominal_alias_identity(
                            formal_resolved.clone(),
                            type_env.clone(),
                            module_name.clone(),
                        );
                        Rc::new({
                            let mut __result = Vec::new();
                            for pred in preds.clone().iter().cloned() {
                                __result.extend(
                                    (*where_refinement_diags_for_predicate(
                                        pred.clone(),
                                        formal_checked.clone(),
                                        value_for_refinement.clone(),
                                        span.clone(),
                                        module_name.clone(),
                                        source_indices.clone(),
                                    ))
                                    .iter()
                                    .cloned(),
                                );
                            }
                            __result
                        })
                    }
                }
            }
        }
    }
}

pub fn with_expected_where_refinement_diags(
    result: Rc<InferResult>,
    expected: Option<Rc<Node>>,
    scope: Rc<InferScope>,
) -> Rc<InferResult> {
    match expected.clone() {
        Some(expected_ty) => match (*result.typed.clone().expr_data.clone()).clone() {
            ExprData::ExprCast => result.clone(),
            _ => Rc::new(InferResult {
                typed: result.typed.clone(),
                diagnostics: v1_rt::concat(
                    result.diagnostics.clone(),
                    where_refinement_mismatch_diags(
                        expected_ty.clone(),
                        result.typed.clone(),
                        result.typed.clone().span.clone(),
                        scope.module_name.clone(),
                        scope.type_env.clone(),
                    ),
                ),
            }),
        },
        None => result.clone(),
    }
}

pub fn infer_expr(
    texpr: Rc<Node>,
    scope: Rc<InferScope>,
    expected: Option<Rc<Node>>,
) -> Rc<InferResult> {
    with_expected_where_refinement_diags(
        infer_expr_body(texpr.clone(), scope.clone(), expected.clone()),
        expected.clone(),
        scope.clone(),
    )
}

pub fn kernel_value_declared_type_mismatch(
    formal: Rc<Node>,
    actual: Rc<Node>,
    type_env: Rc<TypeEnv>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    if (((formal.connective.clone() == Connective::Arrow)
        || (actual.connective.clone() == Connective::Arrow))
        || ((actual.children.clone().len() as i64) > 0))
    {
        false
    } else {
        {
            let formal_base = peel_where_refinement_base(formal.clone(), type_env.clone());
            let actual_name = authored_name_at(source_indices.clone(), actual.clone());
            if ((is_kernel_type(actual_name.clone()) == false)
                || (actual_name.clone() == "Unit".to_string()))
            {
                false
            } else {
                {
                    let formal_name = authored_name_at(source_indices.clone(), formal_base.clone());
                    if (((formal_name.clone() == "".to_string())
                        || (qualified_last_segment(formal_name.clone())
                            == qualified_last_segment(actual_name.clone())))
                        || dag_can_cast(actual_name.clone(), formal_name.clone()))
                    {
                        false
                    } else {
                        if (structural_carrier_template_name(
                            formal_base.clone(),
                            source_indices.clone(),
                        ) == structural_carrier_template_name(
                            actual.clone(),
                            source_indices.clone(),
                        )) {
                            false
                        } else {
                            if is_kernel_type(formal_name.clone()) {
                                true
                            } else {
                                match lookup_type_by_name(type_env.clone(), formal_name.clone()) {
                                    Some(decl) => {
                                        let decl_is_refinement_over_actual =
                                            (((decl.connective.clone() == Connective::Conj)
                                                && ((decl.children.clone().len() as i64) == 1))
                                                && ((decl.type_annotation.clone() != None)
                                                    || match decl.children.clone().first().cloned()
                                                    {
                                                        Some(refinement_child) => {
                                                            (authored_name_at(
                                                                source_indices.clone(),
                                                                refinement_child.clone(),
                                                            ) == actual_name.clone())
                                                        }
                                                        None => false,
                                                    }));
                                        ((((decl.connective.clone() == Connective::Conj)
                                            || (decl.connective.clone() == Connective::Disj))
                                            && ((decl.children.clone().len() as i64) > 0))
                                            && (decl_is_refinement_over_actual.clone() == false))
                                    }
                                    None => false,
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn application_type_name_identity(
    type_name: String,
    type_env: Rc<TypeEnv>,
    module_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    match lookup_type_by_name(type_env.clone(), type_name.clone()) {
        Some(decl) => match decl.inferred.clone().as_deref().cloned() {
            Some(InferredNode::Resolved { node: target, .. }) => authored_name_at(
                source_indices.clone(),
                peel_nominal_alias_identity(target.clone(), type_env.clone(), module_name.clone()),
            ),
            _ => authored_name_at(
                source_indices.clone(),
                peel_nominal_alias_identity(decl.clone(), type_env.clone(), module_name.clone()),
            ),
        },
        None => type_name.clone(),
    }
}

pub fn structured_application_structural_type_name(
    type_name: String,
    scope: Rc<InferScope>,
) -> String {
    application_type_name_identity(
        type_name.clone(),
        scope.type_env.clone(),
        scope.module_name.clone(),
        scope.type_env.clone().source_indices.clone(),
    )
}

pub fn structured_application_record_lit_nominal_name(
    lit_name: String,
    scope: Rc<InferScope>,
) -> String {
    structured_application_structural_type_name(lit_name.clone(), scope.clone())
}

pub fn structured_application_lit_is_declared_optional_variant(
    formal: Rc<Node>,
    lit_name: String,
    scope: Rc<InferScope>,
) -> bool {
    {
        let source_indices = scope.type_env.clone().source_indices.clone();
        let formal_resolved = match lookup_type_for(
            scope.type_env.clone(),
            with_required_cardinality(formal.clone()),
        ) {
            Some(resolved) => resolved.clone(),
            None => with_required_cardinality(formal.clone()),
        };
        if ((formal.return_cardinality.clone() == Cardinality::CardOptional)
            && ((lit_name.clone() == "Present".to_string())
                || (lit_name.clone() == "Absent".to_string())))
        {
            true
        } else {
            has_child_named(
                formal_resolved.clone(),
                lit_name.clone(),
                source_indices.clone(),
            )
        }
    }
}

pub fn application_type_names_compatible(
    formal_name: String,
    lit_name: String,
    type_env: Rc<TypeEnv>,
    module_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    if ((formal_name.clone() == "".to_string()) || (lit_name.clone() == "".to_string())) {
        (formal_name.clone() == lit_name.clone())
    } else {
        if (formal_name.clone() == lit_name.clone()) {
            true
        } else {
            {
                let formal_identity = application_type_name_identity(
                    formal_name.clone(),
                    type_env.clone(),
                    module_name.clone(),
                    source_indices.clone(),
                );
                let lit_identity = application_type_name_identity(
                    lit_name.clone(),
                    type_env.clone(),
                    module_name.clone(),
                    source_indices.clone(),
                );
                if (formal_identity.clone() == lit_identity.clone()) {
                    true
                } else {
                    if dag_can_cast(lit_name.clone(), formal_name.clone()) {
                        true
                    } else {
                        if (type_name_transparently_aliases_to(
                            lit_name.clone(),
                            formal_name.clone(),
                            type_env.clone(),
                            module_name.clone(),
                            source_indices.clone(),
                        ) || type_name_transparently_aliases_to(
                            formal_name.clone(),
                            lit_name.clone(),
                            type_env.clone(),
                            module_name.clone(),
                            source_indices.clone(),
                        )) {
                            true
                        } else {
                            match lookup_type_by_name(type_env.clone(), formal_name.clone()) {
                                Some(formal_decl) => brand_grounds_transparently_to(
                                    lit_name.clone(),
                                    formal_decl.clone(),
                                    type_env.clone(),
                                    source_indices.clone(),
                                ),
                                None => false,
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn type_name_transparently_aliases_to(
    mut alias_name: String,
    mut target_name: String,
    mut type_env: Rc<TypeEnv>,
    mut module_name: String,
    mut source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    loop {
        match lookup_type_by_name(type_env.clone(), alias_name.clone()) {
            Some(decl) => {
                let peeled = peel_nominal_alias_identity(
                    decl.clone(),
                    type_env.clone(),
                    module_name.clone(),
                );
                let peeled_name = authored_name_at(source_indices.clone(), peeled.clone());
                if (peeled_name.clone() == alias_name.clone()) {
                    break false;
                } else {
                    if (peeled_name.clone() == target_name.clone()) {
                        break true;
                    } else {
                        {
                            let __tco_0 = peeled_name.clone();
                            alias_name = __tco_0;
                            continue;
                        }
                    }
                }
            }
            None => {
                break false;
            }
        }
    }
}

pub fn structured_application_site_type_mismatch(
    formal: Rc<Node>,
    actual_expr: Rc<Node>,
    scope: Rc<InferScope>,
) -> bool {
    match (*actual_expr.expr_data.clone()).clone() {
        ExprData::ExprRecordLit { parent_enum: _, .. } => {
            structured_application_site_type_mismatch_with_peeled(
                formal.clone(),
                peel_nominal_alias_identity(
                    formal.clone(),
                    scope.type_env.clone(),
                    scope.module_name.clone(),
                ),
                actual_expr.clone(),
                scope.clone(),
            )
        }
        _ => false,
    }
}

pub fn structured_application_site_type_mismatch_with_peeled(
    formal: Rc<Node>,
    formal_peeled: Rc<Node>,
    actual_expr: Rc<Node>,
    scope: Rc<InferScope>,
) -> bool {
    match (*actual_expr.expr_data.clone()).clone() {
        ExprData::ExprRecordLit { parent_enum: _, .. } => {
            let source_indices = scope.type_env.clone().source_indices.clone();
            if type_node_is_callable(formal_peeled.clone()) {
                false
            } else {
                {
                    let formal_name =
                        authored_name_at(source_indices.clone(), formal_peeled.clone());
                    if (formal_name.clone() == "".to_string()) {
                        false
                    } else {
                        {
                            let formal_structural = structured_application_structural_type_name(
                                formal_name.clone(),
                                scope.clone(),
                            );
                            match record_lit_type_name_at(
                                actual_expr.clone(),
                                source_indices.clone(),
                            ) {
                                Some(lit_name) => {
                                    if application_type_names_compatible(
                                        formal_name.clone(),
                                        lit_name.clone(),
                                        scope.type_env.clone(),
                                        scope.module_name.clone(),
                                        source_indices.clone(),
                                    ) {
                                        false
                                    } else {
                                        {
                                            let lit_nominal =
                                                structured_application_record_lit_nominal_name(
                                                    lit_name.clone(),
                                                    scope.clone(),
                                                );
                                            if ((lit_name.clone() == "".to_string()) || structured_application_lit_is_declared_optional_variant(formal.clone(), lit_name.clone(), scope.clone())) {
                                    false
                                } else {
                                    if match record_lit_alias_struct_expansion(lit_name.clone(), scope.clone()) {
    Some(expansion) => {
                                        let expanded_name = authored_name_at(source_indices.clone(), expansion.resolved.clone());
((expanded_name.clone() == formal_structural.clone()) || application_type_names_compatible(formal_structural.clone(), expanded_name.clone(), scope.type_env.clone(), scope.module_name.clone(), source_indices.clone()))
},
    None => false,
} {
                                        false
                                    } else {
                                        if brand_grounds_transparently_to(lit_name.clone(), formal_peeled.clone(), scope.type_env.clone(), source_indices.clone()) {
                                            false
                                        } else {
                                            if ((((formal_structural.clone() == lit_nominal.clone()) || (formal_structural.clone() == lit_name.clone())) || application_type_names_compatible(formal_structural.clone(), lit_nominal.clone(), scope.type_env.clone(), scope.module_name.clone(), source_indices.clone())) || application_type_names_compatible(formal_structural.clone(), lit_name.clone(), scope.type_env.clone(), scope.module_name.clone(), source_indices.clone())) {
                                                false
                                            } else {
                                                {
                                                    let formal_decl = match lookup_type_for(scope.type_env.clone(), with_required_cardinality(formal_peeled.clone())) {
    Some(resolved) => Some(resolved.clone()),
    None => lookup_type_by_name(scope.type_env.clone(), formal_name.clone()),
};
match formal_decl.clone() {
    Some(decl) => match decl.connective.clone() {
    Connective::Disj => if has_child_named(decl.clone(), lit_name.clone(), source_indices.clone()) {
                                                        false
                                                    } else {
                                                        match variant_owner_node(scope.clone(), lit_name.clone()) {
    Some(owner) => {
                                                            let owner_name = authored_name_at(source_indices.clone(), owner.clone());
!application_type_names_compatible(formal_name.clone(), owner_name.clone(), scope.type_env.clone(), scope.module_name.clone(), source_indices.clone())
},
    None => true,
}
                                                    },
    Connective::Conj => {
                                                        let decl_name = structured_application_structural_type_name(authored_name_at(source_indices.clone(), decl.clone()), scope.clone());
(!application_type_names_compatible(decl_name.clone(), lit_nominal.clone(), scope.type_env.clone(), scope.module_name.clone(), source_indices.clone()) && !application_type_names_compatible(decl_name.clone(), lit_name.clone(), scope.type_env.clone(), scope.module_name.clone(), source_indices.clone()))
},
    _ => false,
},
    None => if is_kernel_type(formal_name.clone()) {
                                                        match lookup_type_by_name(scope.type_env.clone(), lit_name.clone()) {
    Some(lit_decl) => ((lit_decl.connective.clone() == Connective::Conj) || (lit_decl.connective.clone() == Connective::Disj)),
    None => match variant_owner_node(scope.clone(), lit_name.clone()) {
    Some(_) => true,
    None => false,
},
}
                                                    } else {
                                                        if ((lookup_type_by_name(scope.type_env.clone(), lit_name.clone()) != None) && (lookup_type_by_name(scope.type_env.clone(), formal_name.clone()) != None)) {
                                                            true
                                                        } else {
                                                            false
                                                        }
                                                    },
}
}
                                            }
                                        }
                                    }
                                }
                                        }
                                    }
                                }
                                None => false,
                            }
                        }
                    }
                }
            }
        }
        _ => false,
    }
}

pub fn direct_call_structured_record_literal_resolved_type_mismatch(
    formal: Rc<Node>,
    actual_expr: Rc<Node>,
    type_env: Rc<TypeEnv>,
    module_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    match (*actual_expr.expr_data.clone()).clone() {
        ExprData::ExprRecordLit { parent_enum: _, .. } => {
            let formal_peeled =
                peel_nominal_alias_identity(formal.clone(), type_env.clone(), module_name.clone());
            let formal_name = authored_name_at(source_indices.clone(), formal_peeled.clone());
            match record_lit_type_name_at(actual_expr.clone(), source_indices.clone()) {
                Some(lit_name) => {
                    if application_type_names_compatible(
                        formal_name.clone(),
                        lit_name.clone(),
                        type_env.clone(),
                        module_name.clone(),
                        source_indices.clone(),
                    ) {
                        false
                    } else {
                        {
                            let actual_raw = resolved_type(actual_expr.clone());
                            let actual = peel_nominal_alias_identity(
                                actual_raw.clone(),
                                type_env.clone(),
                                module_name.clone(),
                            );
                            direct_call_arg_type_mismatch(
                                formal.clone(),
                                actual.clone(),
                                type_env.clone(),
                                module_name.clone(),
                                source_indices.clone(),
                            )
                        }
                    }
                }
                None => {
                    let actual_raw = resolved_type(actual_expr.clone());
                    let actual = peel_nominal_alias_identity(
                        actual_raw.clone(),
                        type_env.clone(),
                        module_name.clone(),
                    );
                    direct_call_arg_type_mismatch(
                        formal.clone(),
                        actual.clone(),
                        type_env.clone(),
                        module_name.clone(),
                        source_indices.clone(),
                    )
                }
            }
        }
        _ => false,
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CallFormalApplication {
    pub index: i64,
    pub param_name: String,
    pub formal_subst: Rc<Node>,
    pub formal: Rc<Node>,
    pub matched_arg: Option<Rc<Node>>,
}

pub fn call_application_plan_note() -> String {
    thread_local! {
        static CACHED: String = {
            "Cost shape (DESIGN §6 bare-minimum-cost) and single authority (§3). direct_call_arg_mismatch_diags and direct_call_structured_application_mismatch_diags were line-for-line duplicates of the same per-formal prologue: param_node_type_expr, substitute_generics, peel_nominal_alias_identity, authored_name_at, and the named-then-positional actual search. Both run over the SAME value_params, typed_args and call_subst at the one direct-call seam, so every formal was canonicalized twice per call. peel_nominal_alias_identity is resolve_node_bounded, an unmemoized recursive rebuild allocating a fresh Node per level, and it measured as the ENTIRE cost of the conformance seam: on gunbc.host_effect_realize the two timed peels inside direct_call_arg_mismatch_diags accounted for that function to within instrument overhead (62719ms + 62804ms against 125438ms over 330 calls), while the timer around direct_call_arg_type_mismatch never entered the top fourteen operations and substitute_generics already short-circuits an empty substitution. That module holds 63% of all corpus type inference. Building the binding ONCE and passing it to both consumers is the deduplication, not a cache: no map is introduced, so nothing here becomes an order-exposing operation in the v2.std.determinism denominator. Behavior is identical because every recomputed term is a pure function of arguments both callers already share.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn build_call_application_plan(
    value_params: Rc<Vec<Rc<Node>>>,
    typed_args: Rc<Vec<Rc<Node>>>,
    call_subst: Rc<HashMap<String, Rc<Node>>>,
    type_env: Rc<TypeEnv>,
    module_name: String,
) -> Rc<Vec<Rc<CallFormalApplication>>> {
    {
        let source_indices = type_env.source_indices.clone();
        Rc::new({
            let mut __result = Vec::new();
            for pair in Rc::new(
                value_params
                    .clone()
                    .iter()
                    .cloned()
                    .enumerate()
                    .map(|(i, v)| (i as i64, v))
                    .collect::<Vec<_>>(),
            )
            .iter()
            .cloned()
            {
                __result.push({
                    let formal_raw = param_node_type_expr(pair.1.clone());
                    let formal_subst = substitute_generics(
                        formal_raw.clone(),
                        call_subst.clone(),
                        source_indices.clone(),
                    );
                    let param_name = authored_name_at(source_indices.clone(), pair.1.clone());
                    Rc::new(CallFormalApplication {
                        index: pair.0.clone(),
                        param_name: param_name.clone(),
                        formal_subst: formal_subst.clone(),
                        formal: peel_nominal_alias_identity(
                            formal_subst.clone(),
                            type_env.clone(),
                            module_name.clone(),
                        ),
                        matched_arg: match Rc::new({
                            let mut __result = Vec::new();
                            for ta in typed_args.clone().iter().cloned() {
                                if arg_has_name(
                                    ta.clone(),
                                    param_name.clone(),
                                    source_indices.clone(),
                                ) {
                                    __result.push(ta);
                                }
                            }
                            __result
                        })
                        .first()
                        .cloned()
                        {
                            Some(named_ta) => Some(named_ta.clone()),
                            None => typed_args
                                .clone()
                                .iter()
                                .cloned()
                                .skip(pair.0.clone() as usize)
                                .next(),
                        },
                    })
                });
            }
            __result
        })
    }
}

pub fn direct_call_structured_application_mismatch_diags(
    plan: Rc<Vec<Rc<CallFormalApplication>>>,
    scope: Rc<InferScope>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    {
        let type_env = scope.type_env.clone();
        let module_name = scope.module_name.clone();
        let source_indices = type_env.source_indices.clone();
        Rc::new({
            let mut __result = Vec::new();
            for app in plan.clone().iter().cloned() {
                __result.extend(
                    (*{
                        let formal_subst = app.formal_subst.clone();
                        let formal = app.formal.clone();
                        match app.matched_arg.clone() {
                            Some(ta) => {
                                let actual_expr = arg_value(ta.clone());
                                if (structured_application_site_type_mismatch_with_peeled(
                                    formal_subst.clone(),
                                    formal.clone(),
                                    actual_expr.clone(),
                                    scope.clone(),
                                )
                                    || direct_call_structured_record_literal_resolved_type_mismatch(
                                        formal.clone(),
                                        actual_expr.clone(),
                                        type_env.clone(),
                                        module_name.clone(),
                                        source_indices.clone(),
                                    ))
                                {
                                    {
                                        let actual_raw = resolved_type(actual_expr.clone());
                                        let actual = peel_nominal_alias_identity(
                                            actual_raw.clone(),
                                            type_env.clone(),
                                            module_name.clone(),
                                        );
                                        Rc::new(vec![type_mismatch_error(
                                            node_type_shape(formal.clone(), source_indices.clone()),
                                            node_type_shape(actual.clone(), source_indices.clone()),
                                            actual_expr.span.clone(),
                                            module_name.clone(),
                                        )])
                                    }
                                } else {
                                    Rc::new(vec![])
                                }
                            }
                            None => Rc::new(vec![]),
                        }
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        })
    }
}

pub fn container_element_nominal_brand_mismatch(
    formal: Rc<Node>,
    actual: Rc<Node>,
    type_env: Rc<TypeEnv>,
    module_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    if ((node_is_element_collection(formal.clone(), source_indices.clone())
        && node_is_element_collection(actual.clone(), source_indices.clone()))
        && (authored_name_at(source_indices.clone(), formal.clone())
            == authored_name_at(source_indices.clone(), actual.clone())))
    {
        match formal.children.clone().first().cloned() {
            Some(formal_ch) => match actual.children.clone().first().cloned() {
                Some(actual_ch) => {
                    let formal_el = peel_nominal_alias_identity(
                        child_type_node(formal_ch.clone()),
                        type_env.clone(),
                        module_name.clone(),
                    );
                    let actual_el = peel_nominal_alias_identity(
                        child_type_node(actual_ch.clone()),
                        type_env.clone(),
                        module_name.clone(),
                    );
                    nominal_call_arg_brand_mismatch(
                        formal_el.clone(),
                        actual_el.clone(),
                        type_env.clone(),
                        source_indices.clone(),
                    )
                }
                None => false,
            },
            None => false,
        }
    } else {
        false
    }
}

pub fn direct_call_arg_type_mismatch(
    formal: Rc<Node>,
    actual: Rc<Node>,
    type_env: Rc<TypeEnv>,
    module_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    if (type_node_is_callable(formal.clone()) || type_node_is_callable(actual.clone())) {
        false
    } else {
        ((nominal_call_arg_brand_mismatch(
            formal.clone(),
            actual.clone(),
            type_env.clone(),
            source_indices.clone(),
        ) || container_element_nominal_brand_mismatch(
            formal.clone(),
            actual.clone(),
            type_env.clone(),
            module_name.clone(),
            source_indices.clone(),
        )) || kernel_value_declared_type_mismatch(
            formal.clone(),
            actual.clone(),
            type_env.clone(),
            source_indices.clone(),
        ))
    }
}

pub fn borrowed_callable_call_type(
    gnode: Rc<Node>,
    typed_args: Rc<Vec<Rc<Node>>>,
    scope: Rc<InferScope>,
) -> Rc<Node> {
    {
        let source_indices = scope.type_env.clone().source_indices.clone();
        let base = callable_inferred(gnode.clone());
        let tp_names = fn_type_param_names(gnode.clone(), source_indices.clone());
        if ((tp_names.clone().len() as i64) == 0) {
            base
        } else {
            {
                let value_params = Rc::new({
                    let mut __result = Vec::new();
                    for p in gnode.params.clone().iter().cloned() {
                        if !param_is_generic_decl(p.clone(), source_indices.clone()) {
                            __result.push(p);
                        }
                    }
                    __result
                });
                let subst = Rc::new(
                    value_params
                        .clone()
                        .iter()
                        .cloned()
                        .enumerate()
                        .map(|(i, v)| (i as i64, v))
                        .collect::<Vec<_>>(),
                )
                .iter()
                .cloned()
                .fold(
                    v1_rt::rc_empty_map::<String, Rc<Node>>(),
                    |acc: Rc<HashMap<String, Rc<Node>>>, pair: (i64, Rc<Node>)| {
                        let formal_raw = param_node_type_expr(pair.1.clone());
                        let param_name = authored_name_at(source_indices.clone(), pair.1.clone());
                        let matched_arg = match Rc::new({
                            let mut __result = Vec::new();
                            for ta in typed_args.clone().iter().cloned() {
                                if arg_has_name(
                                    ta.clone(),
                                    param_name.clone(),
                                    source_indices.clone(),
                                ) {
                                    __result.push(ta);
                                }
                            }
                            __result
                        })
                        .first()
                        .cloned()
                        {
                            Some(named_ta) => Some(named_ta.clone()),
                            None => typed_args
                                .clone()
                                .iter()
                                .cloned()
                                .skip(pair.0.clone() as usize)
                                .next(),
                        };
                        match matched_arg.clone() {
                            Some(ta) => unify_generics(
                                formal_raw.clone(),
                                resolved_type(arg_value(ta.clone())),
                                tp_names.clone(),
                                source_indices.clone(),
                                acc.clone(),
                            ),
                            None => acc.clone(),
                        }
                    },
                );
                substitute_generics(base, subst.clone(), source_indices.clone())
            }
        }
    }
}

pub fn is_anonymous_bound_name(name: String) -> bool {
    (name.clone() == "_".to_string())
}

pub fn call_arg_label_matches_param(param_name: String, arg_label: String) -> bool {
    (((param_name.clone() == arg_label.clone()) || (param_name.clone() == "_".to_string()))
        || (((v1_rt::string_length(&param_name) >= 1)
            && (v1_rt::substring(&param_name, 0, 1) == "_".to_string()))
            && (v1_rt::substring(&param_name, 1, v1_rt::string_length(&param_name))
                == arg_label.clone())))
}

pub fn param_binds_positionally(
    p: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    match p.children.clone().first().cloned() {
        Some(type_expr) => {
            (authored_name_at(source_indices.clone(), type_expr.clone())
                != authored_name_at(source_indices.clone(), p.clone()))
        }
        None => false,
    }
}

pub fn call_arg_bound_param_at_binding_key_note() -> String {
    thread_local! {
        static CACHED: String = {
            "Runtime (v1_interpreter.rs call_function_inner) keys `bindings` differently per argument form: a NAMED actual is inserted under its own literal caller label (`bindings.insert(ctx.sym(name), ...)` — the raw label, never resolved through the underscore idiom to a declared name), while a POSITIONAL actual is inserted under the declared name it fills by running positional index (`bindings.insert(ctx.sym(&param_names[positional_idx]), ...)`). Two named actuals therefore collide only when they carry the SAME literal label, and a positional-then-named collision (`one(1, a: 2)`) only when the named label equals the positional slot's declared name (found by review 48724). Resolving a named actual's key through declared_names via call_arg_label_matches_param (the prior form of this function) is a DIFFERENT and wrong key: filter-then-first picks whichever declared param the caller-label test hits first in declaration order, and an underscore-named param (`_: Edge`) matches ANY label unconditionally, so a later exact-named actual (`child:` against declared `child`) could be shadowed into colliding with an unrelated earlier underscore-idiom actual (`e:` against declared `_`) even though the runtime keys them apart as \"e\" and \"child\" — the false positive measured live at src/v2/std/cardinality.dag's termination_proof_fold_step(acc:, e:, child:) call against fn termination_proof_fold_step(acc, _: Edge, child), which compiled clean before this correction and fails at this wall after it without the fix.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CallArgBoundParamAccum {
    pub bound: Option<String>,
    pub pos: i64,
}

pub fn call_arg_bound_param_at(
    idx: i64,
    typed_args: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    positionally_eligible_names: Rc<Vec<String>>,
) -> Option<String> {
    Rc::new(
        typed_args
            .clone()
            .iter()
            .cloned()
            .take((idx.clone() + 1) as usize)
            .collect::<Vec<_>>(),
    )
    .iter()
    .cloned()
    .fold(
        Rc::new(CallArgBoundParamAccum {
            bound: None,
            pos: 0,
        }),
        |acc: Rc<CallArgBoundParamAccum>, ta: Rc<Node>| match arg_name_at(
            ta.clone(),
            source_indices.clone(),
        ) {
            Some(label) => Rc::new(CallArgBoundParamAccum {
                bound: Some(label.clone()),
                pos: acc.pos.clone(),
            }),
            None => Rc::new(CallArgBoundParamAccum {
                bound: positionally_eligible_names
                    .clone()
                    .iter()
                    .cloned()
                    .skip(acc.pos.clone() as usize)
                    .next(),
                pos: (acc.pos.clone() + 1),
            }),
        },
    )
    .bound
    .clone()
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CallShapeArityScan {
    pub positional_slot: i64,
    pub required_count: i64,
    pub supplied_count: i64,
    pub deficit_param: Option<Rc<Node>>,
}

pub fn scan_call_shape_arity(
    sig_params: Rc<Vec<Rc<Node>>>,
    typed_args: Rc<Vec<Rc<Node>>>,
    positional_args: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<CallShapeArityScan> {
    sig_params.clone().iter().cloned().fold(
        Rc::new(CallShapeArityScan {
            positional_slot: 0,
            required_count: 0,
            supplied_count: 0,
            deficit_param: None,
        }),
        |st: Rc<CallShapeArityScan>, param: Rc<Node>| {
            if (st.deficit_param.clone() != None) {
                st.clone()
            } else {
                if param_is_generic_decl(param.clone(), source_indices.clone()) {
                    st.clone()
                } else {
                    if (param_node_default_value(param.clone()) != None) {
                        st.clone()
                    } else {
                        {
                            let param_name =
                                authored_name_at(source_indices.clone(), param.clone());
                            let named_supplied = {
                                let mut __found = false;
                                for ta in typed_args.clone().iter().cloned() {
                                    if match arg_name_at(ta.clone(), source_indices.clone()) {
                                        Some(label) => call_arg_label_matches_param(
                                            param_name.clone(),
                                            label.clone(),
                                        ),
                                        None => false,
                                    } {
                                        __found = true;
                                        break;
                                    }
                                }
                                __found
                            };
                            let next_required = (st.required_count.clone() + 1);
                            if named_supplied.clone() {
                                Rc::new(CallShapeArityScan {
                                    positional_slot: st.positional_slot.clone(),
                                    required_count: next_required.clone(),
                                    supplied_count: (st.supplied_count.clone() + 1),
                                    deficit_param: None,
                                })
                            } else {
                                if param_binds_positionally(param.clone(), source_indices.clone()) {
                                    if (st.positional_slot.clone()
                                        < (positional_args.clone().len() as i64))
                                    {
                                        Rc::new(CallShapeArityScan {
                                            positional_slot: (st.positional_slot.clone() + 1),
                                            required_count: next_required.clone(),
                                            supplied_count: (st.supplied_count.clone() + 1),
                                            deficit_param: None,
                                        })
                                    } else {
                                        Rc::new(CallShapeArityScan {
                                            positional_slot: st.positional_slot.clone(),
                                            required_count: next_required.clone(),
                                            supplied_count: st.supplied_count.clone(),
                                            deficit_param: Some(param.clone()),
                                        })
                                    }
                                } else {
                                    Rc::new(CallShapeArityScan {
                                        positional_slot: st.positional_slot.clone(),
                                        required_count: next_required.clone(),
                                        supplied_count: st.supplied_count.clone(),
                                        deficit_param: Some(param.clone()),
                                    })
                                }
                            }
                        }
                    }
                }
            }
        },
    )
}

pub fn direct_call_shape_diags(
    func_name: String,
    sig_params: Rc<Vec<Rc<Node>>>,
    typed_args: Rc<Vec<Rc<Node>>>,
    type_env: Rc<TypeEnv>,
    module_name: String,
    call_span: Rc<SourceSpan>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    {
        let source_indices = type_env.source_indices.clone();
        let declared_names = Rc::new({
            let mut __result = Vec::new();
            for p in sig_params.clone().iter().cloned() {
                __result.push(authored_name_at(source_indices.clone(), p.clone()));
            }
            __result
        });
        let positionally_eligible_names = Rc::new({
            let mut __result = Vec::new();
            for p in Rc::new({
                let mut __result = Vec::new();
                for p in sig_params.clone().iter().cloned() {
                    if param_binds_positionally(p.clone(), source_indices.clone()) {
                        __result.push(p);
                    }
                }
                __result
            })
            .iter()
            .cloned()
            {
                __result.push(authored_name_at(source_indices.clone(), p.clone()));
            }
            __result
        });
        let unknown_label_diags = Rc::new({
            let mut __result = Vec::new();
            for ta in typed_args.clone().iter().cloned() {
                __result.extend(
                    (*match arg_name_at(ta.clone(), source_indices.clone()) {
                        Some(label) => {
                            if {
                                let mut __found = false;
                                for pn in declared_names.clone().iter().cloned() {
                                    if call_arg_label_matches_param(pn.clone(), label.clone()) {
                                        __found = true;
                                        break;
                                    }
                                }
                                __found
                            } {
                                Rc::new(vec![])
                            } else {
                                Rc::new(vec![make_error_node(
                                    Rc::new(CompilerDiagnostic::CallArgumentNameUnknown {
                                        callee: func_name.clone(),
                                        argument: label.clone(),
                                        declared: declared_names.clone(),
                                        span: ta.span.clone(),
                                    }),
                                    module_name.clone(),
                                )])
                            }
                        }
                        None => Rc::new(vec![]),
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let positional_capacity = (Rc::new({
            let mut __result = Vec::new();
            for p in sig_params.clone().iter().cloned() {
                if param_binds_positionally(p.clone(), source_indices.clone()) {
                    __result.push(p);
                }
            }
            __result
        })
        .len() as i64);
        let positional_args = Rc::new({
            let mut __result = Vec::new();
            for ta in typed_args.clone().iter().cloned() {
                if (arg_name_at(ta.clone(), source_indices.clone()) == None) {
                    __result.push(ta);
                }
            }
            __result
        });
        let surplus_diags =
            if ((positional_args.clone().len() as i64) > positional_capacity.clone()) {
                match positional_args
                    .clone()
                    .iter()
                    .cloned()
                    .skip(positional_capacity.clone() as usize)
                    .next()
                {
                    Some(overflow) => Rc::new(vec![make_error_node(
                        Rc::new(CompilerDiagnostic::CallPositionalSurplus {
                            callee: func_name.clone(),
                            supplied: (positional_args.clone().len() as i64),
                            capacity: positional_capacity.clone(),
                            span: overflow.span.clone(),
                        }),
                        module_name.clone(),
                    )]),
                    None => Rc::new(vec![]),
                }
            } else {
                Rc::new(vec![])
            };
        let duplicate_label_diags = Rc::new({
            let mut __result = Vec::new();
            for pair in Rc::new(
                typed_args
                    .clone()
                    .iter()
                    .cloned()
                    .enumerate()
                    .map(|(i, v)| (i as i64, v))
                    .collect::<Vec<_>>(),
            )
            .iter()
            .cloned()
            {
                __result.extend(
                    (*{
                        let current_bound = call_arg_bound_param_at(
                            pair.0.clone(),
                            typed_args.clone(),
                            source_indices.clone(),
                            positionally_eligible_names.clone(),
                        );
                        match current_bound.clone() {
                            Some(bound_name) => {
                                let earlier_dup = {
                                    let mut __found = false;
                                    for other in Rc::new(
                                        typed_args
                                            .clone()
                                            .iter()
                                            .cloned()
                                            .enumerate()
                                            .map(|(i, v)| (i as i64, v))
                                            .collect::<Vec<_>>(),
                                    )
                                    .iter()
                                    .cloned()
                                    {
                                        if ((other.0.clone() < pair.0.clone())
                                            && (call_arg_bound_param_at(
                                                other.0.clone(),
                                                typed_args.clone(),
                                                source_indices.clone(),
                                                positionally_eligible_names.clone(),
                                            )
                                            .as_deref()
                                                == current_bound.clone().as_deref()))
                                        {
                                            __found = true;
                                            break;
                                        }
                                    }
                                    __found
                                };
                                if (earlier_dup.clone()
                                    && !is_anonymous_bound_name(bound_name.clone()))
                                {
                                    Rc::new(vec![make_error_node(
                                        Rc::new(CompilerDiagnostic::CallArgumentDuplicate {
                                            callee: func_name.clone(),
                                            argument: bound_name.clone(),
                                            span: pair.1.clone().span.clone(),
                                        }),
                                        module_name.clone(),
                                    )])
                                } else {
                                    Rc::new(vec![])
                                }
                            }
                            None => Rc::new(vec![]),
                        }
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let arity_scan = scan_call_shape_arity(
            sig_params.clone(),
            typed_args.clone(),
            positional_args.clone(),
            source_indices.clone(),
        );
        let deficit_diags = match arity_scan.deficit_param.clone() {
            Some(missing_param) => Rc::new(vec![make_error_node(
                Rc::new(CompilerDiagnostic::CallPositionalDeficit {
                    callee: func_name.clone(),
                    parameter: authored_name_at(source_indices.clone(), missing_param.clone()),
                    supplied: arity_scan.supplied_count.clone(),
                    required: arity_scan.required_count.clone(),
                    span: call_span.clone(),
                }),
                module_name.clone(),
            )]),
            None => Rc::new(vec![]),
        };
        v1_rt::concat(
            v1_rt::concat(unknown_label_diags.clone(), surplus_diags.clone()),
            v1_rt::concat(duplicate_label_diags.clone(), deficit_diags.clone()),
        )
    }
}

pub fn function_value_call_named_arg_diags(
    func_name: String,
    typed_args: Rc<Vec<Rc<Node>>>,
    type_env: Rc<TypeEnv>,
    module_name: String,
    body_locals: Rc<HashMap<String, bool>>,
    locals: Rc<HashMap<String, Rc<TypeBinding>>>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    match v1_rt::map_get(&body_locals, func_name.clone()) {
        None => Rc::new(vec![]),
        Some(_) => {
            let named_diags = Rc::new({
                let mut __result = Vec::new();
                for ta in typed_args.clone().iter().cloned() {
                    __result.extend(
                        (*match arg_name_at(ta.clone(), type_env.source_indices.clone()) {
                            Some(label) => Rc::new(vec![make_error_node(
                                Rc::new(CompilerDiagnostic::CallNamedArgOnFunctionValue {
                                    callee: func_name.clone(),
                                    argument: label.clone(),
                                    span: ta.span.clone(),
                                }),
                                module_name.clone(),
                            )]),
                            None => Rc::new(vec![]),
                        })
                        .iter()
                        .cloned(),
                    );
                }
                __result
            });
            let arity_diags = match v1_rt::map_get(&locals, func_name.clone()) {
                Some(binding) => {
                    let param_count = (binding.resolved.clone().params.clone().len() as i64);
                    if (param_count.clone() > 0) {
                        {
                            let supplied = (typed_args.clone().len() as i64);
                            if (supplied.clone() > param_count.clone()) {
                                match typed_args
                                    .clone()
                                    .iter()
                                    .cloned()
                                    .skip(param_count.clone() as usize)
                                    .next()
                                {
                                    Some(overflow) => Rc::new(vec![make_error_node(
                                        Rc::new(CompilerDiagnostic::CallPositionalSurplus {
                                            callee: func_name.clone(),
                                            supplied: supplied.clone(),
                                            capacity: param_count.clone(),
                                            span: overflow.span.clone(),
                                        }),
                                        module_name.clone(),
                                    )]),
                                    None => Rc::new(vec![]),
                                }
                            } else {
                                Rc::new(vec![])
                            }
                        }
                    } else {
                        Rc::new(vec![])
                    }
                }
                None => Rc::new(vec![]),
            };
            v1_rt::concat(named_diags.clone(), arity_diags.clone())
        }
    }
}

pub fn function_value_named_application_wall_note() -> String {
    thread_local! {
        static CACHED: String = {
            "WALL (DESIGN §5) — RUNG (§4b): mitigatable minimum for the class named actuals on function-value application. Reason: coverage path (5) — record-field fn value invoked as cfg.callback(a:) via ExprMethodCall — is compile-clean Accepted today and bypasses both this wall and #7519; executing probe function_value_field_method_known_hole_probe (ct_function_value_field_method_known_hole_probe_test) pins that hole and flips to a permanent regression control when the method-call label wall lands. The direct-call label wall (direct_call_shape_wall_note, gunbc#7519) runs only when a module fn sig resolves at the ExprCall seam. Function-value calls route through body_locals shadowing (call_locals_shadow_note): a let-bound or parameter callee skips sig lookup, so named actuals were silently accepted while the emitter's order_typed_call_args cannot reorder them (lookup_func_sig_in_scope returns Absent) and labels are not validated against any declared parameter authority. This wall refuses every named actual when the callee is a body-scope binding — the function-value path — until declaration-identity join can validate labels against the underlying fn. Positional calls on function values stay allowed. Named actuals on direct module/builtin calls (sig resolved) remain on the sibling wall. COVERAGE ACROSS CALLEE PATHS (§4b rung honesty — class rung is the minimum in-scope path, specimens measured by execution): (1) ExprCall bare name in body_locals (fn param, let, match binder, lambda param) — THIS WALL; structurally guaranteed for named actuals on that path. (2) ExprCall bare name with module fn sig resolved — sibling direct_call_shape_wall_note (#7519). (3) Module-level data binding with typed fn value called by bare name (data cb: fn(...) = ...) — NOT body_locals; routes #7519 when lookup resolves (specimen: CallArgumentNameUnknown on cb(a:, b:)). (4) Generic HO param where the arrow is a type variable (agree: F) — body_locals; same wall as (1). (5) Record field holding fn value invoked as cfg.callback(a:) — UNCOVERED HOLE: parser make_call_expr maps ExprFieldAccess callee to ExprMethodCall, not ExprCall; neither this wall nor #7519 runs; specimen compiles clean with named actuals; executing probe function_value_field_method_known_hole_probe. Dissolve-on: method-call / ExprMethodCall argument-label wall (direct_call_shape_wall_note unwalled class (3)). (6) Immediate apply f()(a:) on a call result — syntax parses (make_call_expr default → ExprCall name \"<expr>\"); NOT body_locals, sig does not resolve; neither wall fires on named args; specimen fails InternalError before Accepted (non-identifier ExprCall callee not modeled) — unwritable as Accepted today, not a live compile-clean named-arg hole.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn direct_call_shape_wall_note() -> String {
    thread_local! {
        static CACHED: String = {
            "WALL (DESIGN §5) — the compile seam now refuses the four direct-call shape states the interpreter refuses at runtime, so the two authorities agree instead of one refusing and the other absorbing. The runtime authority is v1_interpreter.rs call_function_inner: a caller label naming no declared parameter raises CallContractMismatch (accepting label x against a declared x, _x, or _ — the deliberately-unused-parameter idiom, mirrored here in call_arg_label_matches_param); a positional argument beyond the positional parameter list raises CallContractMismatch too; a required parameter omitted without a declared default raises CallContractMismatch too (param_node_default_value legitimately fills omissions that carry a default — only non-default params count as required); and a second actual binding under one already-bound parameter key raises CallContractMismatch too ('argument supplied more than once'). Before this wall the compile seam was SILENT on all four, and the divergence was three-way on the first two (measured live, 2026-07-31, the probe-2 receipt in the guarantee-lane census): `sub(a: 10, bb: 3)` against `fn sub(a: Int, b: Int)` compiled with zero diagnostics, the interpreter refused it loudly, and the Rust emitter silently REORDERED it positionally — order_typed_call_args's name-match-else-positional arm bound bb's value to b, so the emitted realization computed an answer the interpreter refuses: two realizations of one program disagreeing silently, the exact state the guarantee ladder calls silent wrongness. The mechanism of the compile silence was the same absorbing fallback one seam over: direct_call_arg_mismatch_diags walks PARAMS and falls back positionally (`typed_args |> skip(pair.first) |> first`) when no arg carries the param's name, so a mislabeled arg is absorbed into a position and only its TYPE is ever judged — the label itself was never a checked fact. This wall checks application shape at the direct-call seam via direct_call_shape_diags: every labeled actual must name a declared parameter (modulo the underscore idiom); unlabeled actuals must fit within the positional capacity; every required parameter (no default) must be supplied by name or positional slot — scan_call_shape_arity mirrors call_function_inner's binding walk, including the same positional-capacity predicate (a param binds positionally iff its type-expr child's authored name differs from its own); and no two actuals may resolve to the same declared parameter — call_arg_bound_param_at (binding-key discipline documented at call_arg_bound_param_at_binding_key_note) resolves each actual, named or positional, to the parameter it fills, mirroring exactly how call_function_inner keys `bindings`. WHY THIS CHECK WAS NEVER UNDER THE v2.* TYPE-JUDGMENT EXEMPTION (historical; the exemption is DELETED as of the cut B change, and this clause is kept in the past tense rather than removed because it records why the two judgments were separable at all): that exemption existed for the TYPE judgment, whose false-positive classes are representation gaps (brand aliases, optionality's two forms, anonymous literals, expansion depth — the conformance wall's four measured classes). A LABEL has no representation: it is a surface string matched against a declared surface string, the same exact-membership judgment the interpreter performs, so the exemption's reason never reached it and this wall always ran over every module including the compiler's own sources. With the exemption gone both judgments now run over every module, and the distinction survives only as the reason the shape wall could land years before the type judgment did. All four diagnostics BLOCK (CallArgumentNameUnknown, CallPositionalSurplus, CallPositionalDeficit, CallArgumentDuplicate — is_error_diagnostic and is_interpreter_blocking_diagnostic default arms), so a refused program never reaches emit — which retires the emission path's silent reorder for Accepted programs at this seam without touching order_typed_call_args: its positional arm remains the legitimate binding rule for unlabeled args, and the states it could absorb are no longer writable in an Accepted program. DELIBERATELY NOT WALLED, with its trigger: method/pipe-seam argument labels — this wall covers the direct-call seam (the sig != none branch); the method-call path binds its arguments through its own inference arms and is the method wall's territory. The subject grain of the climb, stated per the ladder's rung-honesty rule: the classes 'unknown argument label', 'positional surplus', 'missing required argument', and 'a caller label or slot is bound more than once' each move from mitigatable (runtime refusal on the interpretation path; silent wrong output or deferred NoSuchVariable on the emission path) to structurally guaranteed at the direct-call seam — no Accepted program contains one — while the method-pipe path stays at its measured rung, named here rather than implied climbed. DEFICIT REQUIRED-GRAIN RULING (measured 2026-08-05, option b): the only writable shape where scan_call_shape_arity's required set (skip param_is_generic_decl, else require when not positionally supplied) diverges from call_function_inner's is_value_param (`type_expr authored name != param name`) is a param spelled `x: x<...>` — the param name equals the applied-type constructor with a non-leaf type-expr — corpus census `grep -rPno '\\b([a-z_][a-z0-9_]*): \\1<'` over dag/ src/v1/ src/v2/: 0 sites; params with no type-expr child are unwritable from authored surface. This seam refuses that shape as CallPositionalDeficit; the interpreter does not — compile is authoritative here because a non-positional param with no default and no supplied binding cannot be bound; matching the looser runtime predicate would copy an interpreter deficit for symmetry, not prevent silent wrongness. THE CENSUS RECEIPT, run before landing rather than promised after (2026-07-31): the label/surplus wall refused 28 live sites across the [src/v1, dag] regen closure and the dag + src/v2 compile-clean closure, and every one was the same defect — a parameter renamed at its declaration while call sites kept the old label, absorbed positionally ever since: to_string(i:) against the renamed value (8 sites, src/v1/compile.dag), arm_body(arm:) against n, is_import_slot_node(p:) against n, fold_list(init:) against this corpus's declared empty (17 sites, one file), and floor_discovery_walk_failure_refusal_reason(path:) against path_opt. All were relabeled to the declared authority in the same change. The fold_list rows carry the sharpest lesson about WHY compile must hold this fact even where runtime does not: those 17 sites never failed live because the interpreter grounds fold_list natively (label-blind), while call_function_inner would refuse the same label on the user-fn path — so the program's meaning depended on WHICH dispatch tier happened to serve the call, and the label's truth was untested precisely where it was wrong. The wall pins the label to the one declared authority regardless of tier, which is what keeps the call sites correct when the native grounding dissolves into the declared surface (the primitive-realization-single-authority trigger). MEASURED BLIND SPOT, stated rather than implied covered: 3 more to_string(i:) sites in src/v1/dag_collect.dag never reached the wall because their callee resolves NO sig at this seam (no import, global-bare miss) — the sig == none fallthrough routes to the method bridge and this wall never sees the call. They were found by grep on the fossil's shape and fixed with the rest, but the CLASS stays open: a call whose callee sig does not resolve is judged by nothing here, and that fallthrough closes with resolution coverage (the namespace lane), not with a wider label check. (Corrected 2026-08-05: the duplicate-label class LANDED in the order this note originally specified — v1_interpreter.rs call_function_inner now refuses a second binding under one caller label (CallContractMismatch, 'argument supplied more than once') before this seam was given its mirror, CallArgumentDuplicate. The class 'a caller label is supplied more than once' therefore climbs from mitigatable (silent last-write-wins) to structurally guaranteed at the direct-call seam, alongside the other three; a whole-tree census at landing found zero live duplicate-label call sites, so the wall adds no new refusal to any existing corpus form.) (Corrected 2026-08-05, cursor review 48724: an interim version of the duplicate-label mirror keyed CallArgumentDuplicate on exact caller-label string equality, which overclaimed. The runtime authority (call_function_inner) keys `bindings` by resolved PARAMETER symbol, not by caller-label string, and populates that key from a positional bind exactly as it does from a named one — so a positional bind of the sole parameter followed by a same-parameter named actual (`one(1, a: 2)` against `fn one(a: Int)`) collides and refuses at runtime, a state the label-string-only compile check could not see (`Absent => false` for positional predecessors) and so compiled clean, reaching emit. CallArgumentDuplicate is now keyed the same way the runtime is: call_arg_bound_param_at resolves each actual — named or positional — to the declared parameter it fills (positional actuals against the interpreter's own filtered param_binds_positionally list, in running positional order; named actuals through call_arg_label_matches_param, the same underscore-idiom equality unknown-label matching already uses) and the wall refuses a second actual resolving to the same parameter, never comparing raw caller-label strings against each other. The measured false-negative this closes and its discriminating fixture: call_duplicate_mixed_red_source, a single-parameter positional-then-named collision that a label-string-only check could not distinguish from the corpus's positional-only and named-only green controls.) (Corrected 2026-08-05, live cardinality.dag false positive: the prior correction's 'resolves a NAMED actual through call_arg_label_matches_param to a declared parameter' also overclaimed. The runtime keys a named actual under its own LITERAL caller label, never resolved through the underscore idiom to a declared name; only a positional actual is keyed by resolved declared name. Resolving named actuals through declared_names let an underscore-named param (matching ANY label unconditionally) shadow an unrelated later exact-named actual into a false collision — measured live at termination_proof_fold_step(acc: acc, e: e, child: child) against fn termination_proof_fold_step(acc, _: Edge, child), which this wall wrongly refused on 'child' until call_arg_bound_param_at's named branch was corrected to bind directly to the caller's literal label.) (Corrected 2026-08-05, #7848 merge: this note previously described only the label/surplus/deficit trio or only the duplicate-label mirror depending on branch; merging the two PRs' parallel work on this same wall found no consistency defect between the two additions — both diagnostics BLOCK, both use the same declared-parameter binding discipline as their keying authority, and both honor the underscore idiom identically, so the merge is a union of coverage, not a reconciliation of conflicting semantics.) (Corrected 2026-08-05, review from parent session loyal-ant-382: the duplicate-binding key, as landed, keyed EVERY anonymous ('_') parameter under the same literal string regardless of position, so a signature with two or more anonymous parameters bound positionally (or a mix of positional and record-field/method-value invocation of the same signature) false-refused CallArgumentDuplicate on its second anonymous actual — a live specimen, provider_readiness_independence_claim in dag/gunbc/provider_readiness_claim_evidence.dag, carries exactly this shape. The class 'a caller label or slot is bound more than once' does NOT climb to structurally guaranteed for anonymous parameters and never claimed to on a correct reading — 'more than once' presupposes the binding is READ twice, and an anonymous parameter's body cannot read it at all, so two anonymous parameters filled at two positions are two distinct, unreadable slots, not one key bound twice. call_arg_bound_param_at's duplicate check (this file) now excludes a resolved binding of exactly '_' from the collision check via the top-level `is_anonymous_bound_name` function (the earlier-duplicate scan still runs unconditionally; its result is combined with `!is_anonymous_bound_name(name: bound_name)` in the final `if`) — an anonymous parameter can never collide with another anonymous parameter under this authority, named or positional. `is_anonymous_bound_name` is a top-level function rather than an inline comparison for the same reason `call_arg_label_matches_param` already is one in this file: 'what counts as anonymous' is a single fact the whole module should ask one authority for, not a `== '_'` literal repeated ad hoc at each call site that cares — the existing pattern, not a new one. The runtime mirror (v1_interpreter.rs call_function_inner) excludes '_' from its collision check the same way, but — unlike an outright exclusion from binding — still INSERTS the value under the '_' key on every anonymous bind: the insert is what the required-argument check (`param_supplied_at_call`, reading `bindings.contains_key`) depends on to see an anonymous parameter as filled, so removing the insert entirely (the fix's first, corrected draft) turned every anonymous-but-positionally-supplied parameter into a false CallPositionalDeficit/'missing required argument' one layer downstream of the duplicate check it was fixing. Harmless repeated overwrite under one dead key, never read by the body, is the correct shape here — not 'never bound' literally, but 'never checked for collision, and immaterial which write wins.' The two required regression fixtures: a call binding two-or-more anonymous parameters positionally (direct and via a stored function value) stays ACCEPTED; the existing named/mixed duplicate fixtures (call_duplicate_mixed_red_source, the cardinality.dag underscore-shadow control) stay RED, because those collide on a NAMED, readable label, not an anonymous one.)".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn direct_call_arg_mismatch_diags(
    plan: Rc<Vec<Rc<CallFormalApplication>>>,
    type_env: Rc<TypeEnv>,
    module_name: String,
) -> Rc<Vec<Rc<ErrorNode>>> {
    {
        let source_indices = type_env.source_indices.clone();
        Rc::new({
            let mut __result = Vec::new();
            for app in plan.clone().iter().cloned() {
                __result.extend(
                    (*{
                        let formal = app.formal.clone();
                        match app.matched_arg.clone() {
                            Some(ta) => {
                                let actual_expr = arg_value(ta.clone());
                                if match (*actual_expr.expr_data.clone()).clone() {
                                    ExprData::ExprRecordLit { parent_enum: _, .. } => true,
                                    _ => false,
                                } {
                                    Rc::new(vec![])
                                } else {
                                    {
                                        let actual_raw = resolved_type(actual_expr.clone());
                                        let actual = peel_nominal_alias_identity(
                                            actual_raw.clone(),
                                            type_env.clone(),
                                            module_name.clone(),
                                        );
                                        if direct_call_arg_type_mismatch(
                                            formal.clone(),
                                            actual.clone(),
                                            type_env.clone(),
                                            module_name.clone(),
                                            source_indices.clone(),
                                        ) {
                                            Rc::new(vec![type_mismatch_error(
                                                node_type_shape(
                                                    formal.clone(),
                                                    source_indices.clone(),
                                                ),
                                                node_type_shape(
                                                    actual.clone(),
                                                    source_indices.clone(),
                                                ),
                                                actual_expr.span.clone(),
                                                module_name.clone(),
                                            )])
                                        } else {
                                            Rc::new(vec![])
                                        }
                                    }
                                }
                            }
                            None => Rc::new(vec![]),
                        }
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        })
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct Tier2bBt {
    pub bt: Rc<Node>,
    pub kernel_diags: Rc<Vec<Rc<ErrorNode>>>,
}

pub fn infer_tier2b_builtin_with_kernel_diags(
    func_name: String,
    typed_args: Rc<Vec<Rc<Node>>>,
    scope: Rc<InferScope>,
    span: Rc<SourceSpan>,
) -> Rc<Tier2bBt> {
    if ((func_name.clone() == "lookup".to_string()) || (func_name.clone() == "map_get".to_string()))
    {
        Rc::new(Tier2bBt {
            bt: match typed_args.clone().first().cloned() {
                Some(receiver_arg) => match arg_value(receiver_arg.clone())
                    .inferred
                    .clone()
                    .as_deref()
                    .cloned()
                {
                    Some(InferredNode::Resolved {
                        node: receiver_type,
                        ..
                    }) => {
                        match map_value_type_in_env(receiver_type.clone(), scope.type_env.clone()) {
                            Some(value_type) => with_optional_cardinality(value_type.clone()),
                            None => resolve_builtin_call_type(func_name.clone()),
                        }
                    }
                    _ => resolve_builtin_call_type(func_name.clone()),
                },
                None => resolve_builtin_call_type(func_name.clone()),
            },
            kernel_diags: Rc::new(vec![]),
        })
    } else {
        if ((func_name.clone() == "map_keys".to_string())
            || (func_name.clone() == "sorted_map_keys".to_string()))
        {
            match typed_args.clone().first().cloned() {
                Some(receiver_arg) => match arg_value(receiver_arg.clone())
                    .inferred
                    .clone()
                    .as_deref()
                    .cloned()
                {
                    Some(InferredNode::Resolved {
                        node: receiver_type,
                        ..
                    }) => {
                        match map_key_type_in_env(receiver_type.clone(), scope.type_env.clone()) {
                            Some(key_type) => {
                                let lk = list_kernel_ty_from_element(key_type.clone());
                                Rc::new(Tier2bBt {
                                    bt: lk.ty.clone(),
                                    kernel_diags: lk.miss_diags.clone(),
                                })
                            }
                            None => Rc::new(Tier2bBt {
                                bt: resolve_builtin_call_type(func_name.clone()),
                                kernel_diags: Rc::new(vec![]),
                            }),
                        }
                    }
                    _ => Rc::new(Tier2bBt {
                        bt: resolve_builtin_call_type(func_name.clone()),
                        kernel_diags: Rc::new(vec![]),
                    }),
                },
                None => Rc::new(Tier2bBt {
                    bt: resolve_builtin_call_type(func_name.clone()),
                    kernel_diags: Rc::new(vec![]),
                }),
            }
        } else {
            if (func_name.clone() == "map_values".to_string()) {
                match typed_args.clone().first().cloned() {
                    Some(receiver_arg) => match arg_value(receiver_arg.clone())
                        .inferred
                        .clone()
                        .as_deref()
                        .cloned()
                    {
                        Some(InferredNode::Resolved {
                            node: receiver_type,
                            ..
                        }) => match map_value_type_in_env(
                            receiver_type.clone(),
                            scope.type_env.clone(),
                        ) {
                            Some(value_type) => {
                                let lv = list_kernel_ty_from_element(value_type.clone());
                                Rc::new(Tier2bBt {
                                    bt: lv.ty.clone(),
                                    kernel_diags: lv.miss_diags.clone(),
                                })
                            }
                            None => Rc::new(Tier2bBt {
                                bt: resolve_builtin_call_type(func_name.clone()),
                                kernel_diags: Rc::new(vec![]),
                            }),
                        },
                        _ => Rc::new(Tier2bBt {
                            bt: resolve_builtin_call_type(func_name.clone()),
                            kernel_diags: Rc::new(vec![]),
                        }),
                    },
                    None => Rc::new(Tier2bBt {
                        bt: resolve_builtin_call_type(func_name.clone()),
                        kernel_diags: Rc::new(vec![]),
                    }),
                }
            } else {
                if (((func_name.clone() == "set_insert".to_string())
                    || (func_name.clone() == "set_union".to_string()))
                    || (func_name.clone() == "set_contains".to_string()))
                {
                    {
                        let operand_elem = if ((func_name.clone() == "set_insert".to_string())
                            || (func_name.clone() == "set_contains".to_string()))
                        {
                            match typed_args.clone().iter().cloned().skip(1 as usize).next() {
                                Some(insert_arg) => match arg_value(insert_arg.clone())
                                    .inferred
                                    .clone()
                                    .as_deref()
                                    .cloned()
                                {
                                    Some(InferredNode::Resolved { node: elem, .. }) => {
                                        Some(elem.clone())
                                    }
                                    _ => None,
                                },
                                None => None,
                            }
                        } else {
                            match typed_args.clone().iter().cloned().skip(1 as usize).next() {
                                Some(other_arg) => match arg_value(other_arg.clone())
                                    .inferred
                                    .clone()
                                    .as_deref()
                                    .cloned()
                                {
                                    Some(InferredNode::Resolved {
                                        node: other_type, ..
                                    }) => match set_element_type_in_env(
                                        other_type.clone(),
                                        scope.type_env.clone(),
                                    ) {
                                        Some(elem_slot) => Some(child_type_node(elem_slot.clone())),
                                        None => None,
                                    },
                                    _ => None,
                                },
                                None => None,
                            }
                        };
                        let recv_is_set = match typed_args.clone().first().cloned() {
                            Some(receiver_arg) => {
                                set_builtin_receiver_is_set(receiver_arg.clone(), scope.clone())
                            }
                            None => false,
                        };
                        let union_other_bad = if (func_name.clone() == "set_union".to_string()) {
                            match typed_args.clone().iter().cloned().skip(1 as usize).next() {
                                Some(other_arg) => set_union_other_operand_is_resolved_non_set(
                                    other_arg.clone(),
                                    scope.clone(),
                                ),
                                None => false,
                            }
                        } else {
                            false
                        };
                        let recv_elem = match typed_args.clone().first().cloned() {
                            Some(receiver_arg) => match arg_value(receiver_arg.clone())
                                .inferred
                                .clone()
                                .as_deref()
                                .cloned()
                            {
                                Some(InferredNode::Resolved {
                                    node: receiver_type,
                                    ..
                                }) => set_element_type_from_receiver(
                                    receiver_type.clone(),
                                    scope.clone(),
                                ),
                                _ => None,
                            },
                            None => None,
                        };
                        let elem_mismatch = match recv_elem.clone() {
                            Some(re) => match operand_elem.clone() {
                                Some(oe) => set_element_types_mismatch(
                                    re.clone(),
                                    oe.clone(),
                                    scope.type_env.clone().source_indices.clone(),
                                ),
                                None => false,
                            },
                            None => false,
                        };
                        let wrong_receiver_diags = if recv_is_set.clone() {
                            Rc::new(vec![])
                        } else {
                            Rc::new(vec![inference_error(
                                v1_rt::concat(
                                    func_name.clone(),
                                    " receiver must be a Set".to_string(),
                                ),
                                span.clone(),
                                scope.module_name.clone(),
                            )])
                        };
                        let wrong_union_other_diags = if union_other_bad.clone() {
                            Rc::new(vec![inference_error(
                                "set_union second operand must be a Set".to_string(),
                                span.clone(),
                                scope.module_name.clone(),
                            )])
                        } else {
                            Rc::new(vec![])
                        };
                        let mismatch_diags = if elem_mismatch.clone() {
                            Rc::new(vec![inference_error(
                                v1_rt::concat(
                                    func_name.clone(),
                                    " incompatible set element types".to_string(),
                                ),
                                span.clone(),
                                scope.module_name.clone(),
                            )])
                        } else {
                            Rc::new(vec![])
                        };
                        let result_bt = if (func_name.clone() == "set_contains".to_string()) {
                            if (recv_is_set.clone() && !elem_mismatch.clone()) {
                                bool_type()
                            } else {
                                resolve_builtin_call_type(func_name.clone())
                            }
                        } else {
                            match typed_args.clone().first().cloned() {
                                Some(receiver_arg) => {
                                    if ((recv_is_set.clone() && !elem_mismatch.clone())
                                        && !union_other_bad.clone())
                                    {
                                        match arg_value(receiver_arg.clone())
                                            .inferred
                                            .clone()
                                            .as_deref()
                                            .cloned()
                                        {
                                            Some(InferredNode::Resolved {
                                                node: receiver_type,
                                                ..
                                            }) => match recv_elem.clone() {
                                                Some(_) => receiver_type.clone(),
                                                None => match operand_elem.clone() {
                                                    Some(element) => {
                                                        set_kernel_ty_from_element(element.clone())
                                                            .ty
                                                            .clone()
                                                    }
                                                    None => {
                                                        resolve_builtin_call_type(func_name.clone())
                                                    }
                                                },
                                            },
                                            _ => resolve_builtin_call_type(func_name.clone()),
                                        }
                                    } else {
                                        resolve_builtin_call_type(func_name.clone())
                                    }
                                }
                                None => resolve_builtin_call_type(func_name.clone()),
                            }
                        };
                        let build_diags = if (func_name.clone() == "set_contains".to_string()) {
                            Rc::new(vec![])
                        } else {
                            match operand_elem.clone() {
                                Some(element) => {
                                    if ((recv_is_set.clone() && !elem_mismatch.clone())
                                        && !union_other_bad.clone())
                                    {
                                        set_kernel_ty_from_element(element.clone())
                                            .miss_diags
                                            .clone()
                                    } else {
                                        Rc::new(vec![])
                                    }
                                }
                                None => Rc::new(vec![]),
                            }
                        };
                        Rc::new(Tier2bBt {
                            bt: result_bt.clone(),
                            kernel_diags: v1_rt::concat(
                                wrong_receiver_diags.clone(),
                                v1_rt::concat(
                                    wrong_union_other_diags.clone(),
                                    v1_rt::concat(mismatch_diags.clone(), build_diags.clone()),
                                ),
                            ),
                        })
                    }
                } else {
                    Rc::new(Tier2bBt {
                        bt: resolve_builtin_call_type(func_name.clone()),
                        kernel_diags: Rc::new(vec![]),
                    })
                }
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct MethodPipeFallback {
    pub result_ty: Rc<Node>,
    pub kernel_diags: Rc<Vec<Rc<ErrorNode>>>,
}

pub fn method_existence_decision(
    recv_rt: Rc<Node>,
    method_name: String,
    scope: Rc<InferScope>,
    span: Rc<SourceSpan>,
) -> Rc<MethodPipeFallback> {
    {
        let recv_shape = node_type_shape(
            recv_rt.clone(),
            scope.type_env.clone().source_indices.clone(),
        );
        let recv_surface_established = (kernel_profile_lookup(authored_name_at(
            scope.type_env.clone().source_indices.clone(),
            recv_rt.clone(),
        )) != None);
        if recv_surface_established.clone() {
            Rc::new(MethodPipeFallback {
                result_ty: error_type(),
                kernel_diags: Rc::new(vec![make_error_node(
                    Rc::new(CompilerDiagnostic::MethodNotFound {
                        method: method_name.clone(),
                        receiver_type: recv_shape.clone(),
                        span: span.clone(),
                    }),
                    scope.module_name.clone(),
                )]),
            })
        } else {
            {
                let peeled = peel_where_refinement_base(recv_rt.clone(), scope.type_env.clone());
                let peeled_lookup = lookup_structural_method(
                    peeled.clone(),
                    method_name.clone(),
                    scope.type_env.clone().source_indices.clone(),
                );
                match peeled_lookup.resolution.clone() {
                    Some(mfr) => Rc::new(MethodPipeFallback {
                        result_ty: mfr.result_type.clone(),
                        kernel_diags: peeled_lookup.kernel_diagnostics.clone(),
                    }),
                    None => {
                        let peeled_shape = node_type_shape(
                            peeled.clone(),
                            scope.type_env.clone().source_indices.clone(),
                        );
                        let peeled_surface_established = (kernel_profile_lookup(authored_name_at(
                            scope.type_env.clone().source_indices.clone(),
                            peeled.clone(),
                        )) != None);
                        if peeled_surface_established.clone() {
                            Rc::new(MethodPipeFallback {
                                result_ty: error_type(),
                                kernel_diags: Rc::new(vec![make_error_node(
                                    Rc::new(CompilerDiagnostic::MethodNotFound {
                                        method: method_name.clone(),
                                        receiver_type: peeled_shape.clone(),
                                        span: span.clone(),
                                    }),
                                    scope.module_name.clone(),
                                )]),
                            })
                        } else {
                            match unresolved_method_frontier_trigger(
                                scope.module_name.clone(),
                                method_name.clone(),
                                recv_shape.clone(),
                            ) {
                                Some(trigger) => {
                                    if (authored_name_at(
                                        scope.type_env.clone().source_indices.clone(),
                                        recv_rt.clone(),
                                    ) == "".to_string())
                                    {
                                        Rc::new(MethodPipeFallback {
                                            result_ty: error_type(),
                                            kernel_diags: Rc::new(vec![make_error_node(
                                                Rc::new(
                                                    CompilerDiagnostic::ReceiverTypeUnestablished {
                                                        method: method_name.clone(),
                                                        span: span.clone(),
                                                    },
                                                ),
                                                scope.module_name.clone(),
                                            )]),
                                        })
                                    } else {
                                        Rc::new(MethodPipeFallback {
    result_ty: error_type(),
    kernel_diags: Rc::new(vec![make_error_node(Rc::new(CompilerDiagnostic::MethodExistenceFrontierAdmitted {
    method: method_name.clone(),
    receiver_type: recv_shape.clone(),
    trigger: dissolution_description(trigger.clone()),
    span: span.clone(),
}), scope.module_name.clone())]),
})
                                    }
                                }
                                None => Rc::new(MethodPipeFallback {
                                    result_ty: error_type(),
                                    kernel_diags: Rc::new(vec![make_error_node(
                                        Rc::new(CompilerDiagnostic::MethodExistenceUndecided {
                                            method: method_name.clone(),
                                            receiver_type: recv_shape.clone(),
                                            span: span.clone(),
                                        }),
                                        scope.module_name.clone(),
                                    )]),
                                }),
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn method_pipe_map_keys_values_fallback(
    recv_rt: Rc<Node>,
    method_name: String,
    scope: Rc<InferScope>,
    span: Rc<SourceSpan>,
) -> Rc<MethodPipeFallback> {
    if ((method_name.clone() == "map_keys".to_string())
        || (method_name.clone() == "sorted_map_keys".to_string()))
    {
        match map_key_type_in_env(recv_rt.clone(), scope.type_env.clone()) {
            Some(key_type) => {
                let lk = list_kernel_ty_from_element(key_type.clone());
                Rc::new(MethodPipeFallback {
                    result_ty: lk.ty.clone(),
                    kernel_diags: lk.miss_diags.clone(),
                })
            }
            None => method_existence_decision(
                recv_rt.clone(),
                method_name.clone(),
                scope.clone(),
                span.clone(),
            ),
        }
    } else {
        if (method_name.clone() == "map_values".to_string()) {
            match map_value_type_in_env(recv_rt.clone(), scope.type_env.clone()) {
                Some(value_type) => {
                    let lv = list_kernel_ty_from_element(value_type.clone());
                    Rc::new(MethodPipeFallback {
                        result_ty: lv.ty.clone(),
                        kernel_diags: lv.miss_diags.clone(),
                    })
                }
                None => method_existence_decision(
                    recv_rt.clone(),
                    method_name.clone(),
                    scope.clone(),
                    span.clone(),
                ),
            }
        } else {
            method_existence_decision(
                recv_rt.clone(),
                method_name.clone(),
                scope.clone(),
                span.clone(),
            )
        }
    }
}

pub fn method_existence_wall_note() -> String {
    thread_local! {
        static CACHED: String = {
            "WALL (DESIGN §5) — an unresolved method REFUSES; it never inherits the receiver type. The deleted else-arm returned recv_rt with an EMPTY diagnostic list, so an unknown method on List<T> became another List<T>: a success-shaped answer that survived a whole collection pipeline, stamped PlainMethodSemantics as if it had resolved. Nothing refused until InterpError::Unimplemented { what: \"method 'filter_map'\" } — whole-tree compile reported ZERO blocking errors while live dispatch returned HTTP 500 (#7479). THE DECIDABILITY PREDICATE IS THE LOAD-BEARING PART. It is PER-RECEIVER, not per-name: refuse exactly when kernel_profile_lookup returns a profile for the receiver canonical container kind, because tier0 (lookup_structural_method) has already consulted that profile algebra templates and missed — so reaching this arm with a kernel-profiled receiver PROVES the method is absent from that receiver complete declared surface. This is the same authority tier0 reads, not a second relation minted here (§3). A NAME-GRAIN PREDICATE WAS TRIED AND IS WRONG, and the receipt is worth keeping because it is subtle: gating on membership in a declared method-name roster admits any rostered name on ANY receiver, so List<Int> |> starts_with(..) and List<Int> |> to_upper() compiled clean while the diagnostic claimed the receiver was under-resolved — a fail-open with a message that also LIED about its cause, since Container(List,Primitive(Int)) is fully resolved (codex review 45327, confirmed by execution). Per-receiver closes both: those two now REFUSE. THE ONE MEASURED OBSTACLE TO PER-RECEIVER WAS A REAL §3 FORK, AND IT IS FIXED HERE RATHER THAN WORKED AROUND: free_monoid_scalar_templates omitted count while the interpreter dispatches it natively on strings (the length/count/size arm), so String |> count reached this arm and was admitted only by the fail-open — a hollow green. count is now declared on the String profile, matching the runtime, so it resolves at tier0 and never reaches here. WHAT STAYS UNDECIDED, and why refusing there would fabricate: a receiver with NO kernel profile has no complete declared surface to prove absence against. THE LARGEST MEASURED CLASS WAS NOT UNDECIDABLE AT ALL AND IS NOW DECIDED — a where-refinement alias arrived as Product(NonEmptyStr) only because resolve_method_receiver_type short-circuits on Conj and never peeled to the String base; peeling it (where_refinement_receiver_peel_note) moved 12 corpus sites out of this residue in both directions at once, resolving the correct .length() calls AND making a bogus method on a branded string a hard MethodNotFound. What remains genuinely has no surface: a lambda parameter whose type never propagates so the receiver has no authored name at all (the LexMatchThunk { apply: fn(s) } idiom in src/v2/compiler/01_tokenize.dag and the StoreObjectFold lambdas in extdeps/git/object_store.dag), a coproduct payload bound by pattern destructuring arriving typed Primitive(ok) (a correct labels |> list_push(label)), a bare type variable, and an Optional whose cardinality is dropped before lookup so the inner product is what arrives. Refusing those would red correct code, which is the mirror image of the fabricated success this wall deletes. A RECEIVER WITH NO AUTHORED NAME AT ALL is not weak evidence about the method — it is no evidence about anything, because the receiver's own type was never established upstream. That is a different judgment failure from 'this receiver has a surface and the method is not on it', so it carries its own diagnostic, ReceiverTypeUnestablished, whose message names that cause instead of implying the method is missing. THE DIAGNOSTIC NAMES THE CAUSE; THE ROSTER BOUNDS THE ADMISSION, and separating those two was a correction. The class was first admitted on the CAUSE alone — any anonymous receiver, non-blocking — on the reasoning that the wall cannot tell an existing method from a nonexistent one when the receiver has no type, so refusing would refuse both. That reasoning is sound about DECIDABILITY and wrong about ADMISSION: it made every future anonymous-receiver call green, including one whose method does not exist, so the exception was unbounded exactly where existence is unknown (codex review 45459). Counting a diagnostic does not stop invalid code reaching the live system. Admission is now gated on the same declared roster as every other unestablished shape, keyed (module, method, Primitive()), so the seven measured occurrences are admitted and a new one anywhere else REFUSES as MethodExistenceUndecided. That is a ratchet that can only shrink, and blocking a new instance of a known deficit is the factory model rather than an inconvenience. Everything that has a name but no surface stays in the same shape-keyed roster. MethodExistenceUndecided carries what is left as a typed, located, COUNTED non-blocking diagnostic (the is_error_diagnostic partition, UnlistedImportUse precedent) so the frequency stays observable and prioritizable rather than zeroed by construction — and it now means exactly ONE thing, receiver surface not established, rather than doubling as a name-grain escape. Both arms return error_type, never recv_rt, so one located refusal does not cascade downstream. AND THE WALL IS REACHED FROM EVERY ARM, WHICH IT WAS NOT AT FIRST: the decision lived inline in the final else of method_pipe_map_keys_values_fallback, so an unresolved map_keys, sorted_map_keys or map_values whose receiver is not a keyed collection took an EARLIER branch and returned recv_rt with an empty diagnostic list — the identical success-shaped fallback this wall exists to delete, preserved in the two special cases that ran before it (codex review 45430). A wall reachable only from the default arm is not a wall, and prose about the default arm cannot see the two arms in front of it. The decision is now method_existence_decision, held once and called from all three, with the control run against the prior binary rather than reasoned about: List<Int> |> map_keys and |> map_values compile with exit 0 on the pre-routing binary and produce two located MethodNotFound refusals on this one. Positive controls: map/filter/fold/flat_map resolve at tier0 and service ops at tier1, neither reaching this arm. THE UPSTREAM DEFECTS ARE NAMED BY THE MEASUREMENT, one fixed here and the rest left as promotion triggers that would each let the wall decide a further non-kernel receiver: (1) FIXED — a where-refinement alias resolving to a Product shape instead of peeling to its declared base before method lookup; (2) a lambda parameter receiver whose type never propagates from the declared fn type it is bound under; (3) a coproduct payload binding typed as the VARIANT name rather than the field type; (4) an optional receiver whose cardinality is dropped so the inner product reaches lookup in place of Optional own surface. Each is carried as a row in unresolved_method_frontier, keyed on the receiver shape that is the evidence for it, except (2) which is the ReceiverTypeUnestablished cause class above. THE INSTRUMENT WAS WRONG BEFORE THE WALL WAS, and that is the most transferable thing here: this wall was measured with `gunbc run --entry dag/tools/generated_artifact_gate.dag`, which reaches only that gate's import closure, and it reported CLEAN while twelve real sites sat outside it — they surfaced from CI instead. The whole-corpus instrument is `gunbc compile --source-root dag --source-root src/v2 --target dag`, the same compile-clean gate CI runs, and it resolves 1629 sources against 2740 indexed modules. A narrow instrument reporting clean is indistinguishable from a wall that works, which is the §5 specification-without-execution trap wearing the shape of a green run. A FOURTH SHAPE was then found and NOT fixed: a brand alias can also arrive as a plain qualified LEAF (Primitive(std.types.NonEmptyStr)) rather than the refinement Conj the peel walks. Three head-resolution strategies were implemented and measured against it — lookup_type_for on the node, lookup_type_by_name on the qualified name, and on its last segment — none recovered the refinement, so the machinery was DELETED rather than shipped unproven and the site is a declared row. Unproven machinery that decides nothing is worse than a declared row that admits what it cannot decide. Dissolve-on: primitive-realization-single-authority — one PrimitiveDefinition identity joining semantic definition, interpreter dispatch and per-target emit handler, at which point every receiver has a complete surface, the count-style forks are unwritable rather than hand-reconciled, and MethodExistenceUndecided is deleted.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn where_refinement_receiver_peel_note() -> String {
    thread_local! {
        static CACHED: String = {
            "A where-refinement type is a Conj carrying its base as its single child and its predicates in type_annotation, and resolve_method_receiver_type SHORT-CIRCUITS on connective == Conj — it treats any product as already-structural and returns it untouched. So NonEmptyStr, declared `String where non_empty`, reached method lookup as Product(NonEmptyStr) and String's algebra profile was never consulted: `.length()` on a branded string had no surface to resolve against and no surface to prove absence against either, which put 12 correct corpus sites (8 in extdeps.filesystem.linux, 4 across gunbc.design) in the wall's undecided residue. This peel is the fix, and the FIRST version of it was a §3 violation that this note asserted its way past — worth recording, because the note is where the defect actually lived. It hand-rolled a second recursive walker over the Conj/annotation/single-child shape and then CLAIMED, in this sentence, that the refinement chain had one traversal authority and the peel was its second consumer. Both walkers independently encoded the shape test, the lookup_type_for base resolution and the recursion, so they could drift apart silently; the prose asserted the property instead of the code establishing it (codex review 45410). WHY THESE READ NODE STORAGE DIRECTLY, since it is asked and the answer is not a per-function one: they are 2 of the 589 direct Node-storage reads in this file (579 of them on origin/main), which is the v1 seed's pervasive and only idiom — the seed IS the traversal, the stage that walks the tree so that later stages need not. There is no canonical query or fold surface reachable from here: fold_node and node_query live in src/v2/std, no v1 seed module imports v2 at all, and v1 COMPILES v2, so routing v1 inference through v2's fold inverts the bootstrap rather than tidying it. DESIGN's fold_node line is scoped to the 7 v2 stages and is a DRY example within v2, not a rule binding the seed. So the disposition here is the SEED'S disposition, the same trigger the hand-Rust receipt carries — the v1 seed shrinks to zero at v2 self-host and these dissolve with it — and attaching a separate per-function trigger to 2 reads while 587 identical reads beside them carry none would be a fabricated bound, describing separable work that does not exist (codex review 45570). The repair is the extraction the claim described: where_refinement_chain is the one walk, it yields the refinement chain from the surface alias down to its ground base, and it has exactly two consumers — type_where_refinement_predicates_transitive flat_maps the immediate predicates over the chain, and peel_where_refinement_base takes its last link. The shape test itself is is_where_refinement_type, held once. Now there is one traversal authority, and it is one because the code says so. It runs only where the wall was already about to refuse or admit, so no previously-resolving call changes meaning; tier0 keeps first claim on the unpeeled receiver, which is what preserves a method declared on the brand itself. The consequence that matters is not that 12 sites went green — it is that they became DECIDABLE IN BOTH DIRECTIONS: once the peeled receiver is kernel-profiled, a method genuinely absent from String now refuses as MethodNotFound instead of resting in the frontier. Widening what the wall can decide is the only move that shrinks the frontier without either fabricating a success or fabricating a refusal.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct UnresolvedMethodFrontierRow {
    pub module_name: String,
    pub method: String,
    pub receiver_shape: String,
    pub occurrences: i64,
    pub cause: String,
    pub dissolution: Rc<DissolutionCondition>,
}

pub fn unresolved_method_frontier() -> Rc<Vec<Rc<UnresolvedMethodFrontierRow>>> {
    Rc::new(vec![Rc::new(UnresolvedMethodFrontierRow {
    module_name: "v2.compiler.tokenize".to_string(),
    method: "apply".to_string(),
    occurrences: 7,
    receiver_shape: "Primitive()".to_string(),
    cause: "receiver is a lambda parameter whose type is never inferred, so it arrives with NO authored name at all. The call is a product FIELD holding a callable — the LexMatchThunk { apply: fn(s) } idiom — not a method at all.".to_string(),
    dissolution: unbound_dissolution("lambda-parameter receiver typing, so the receiver resolves to its declared product and apply is found as a field".to_string()),
}), Rc::new(UnresolvedMethodFrontierRow {
    module_name: "extdeps.git.object_store".to_string(),
    method: "map".to_string(),
    occurrences: 2,
    receiver_shape: "Primitive()".to_string(),
    cause: "receiver is `tree.entries` where `tree` is the parameter of a lambda stored in a StoreObjectFold record field, so the field's declared fn type never reaches the lambda's parameter and the projection off it has no established type.".to_string(),
    dissolution: unbound_dissolution("lambda-parameter receiver typing from the declared fn type of the record field the lambda is stored in".to_string()),
}), Rc::new(UnresolvedMethodFrontierRow {
    module_name: "extdeps.git.object_store".to_string(),
    method: "flat_map".to_string(),
    occurrences: 1,
    receiver_shape: "Primitive()".to_string(),
    cause: "same StoreObjectFold lambda-parameter shape as the `map` row above; listed separately because the key names one method on one receiver shape, never a module-wide pass.".to_string(),
    dissolution: unbound_dissolution("lambda-parameter receiver typing from the declared fn type of the record field the lambda is stored in".to_string()),
}), Rc::new(UnresolvedMethodFrontierRow {
    module_name: "extdeps.mercurial".to_string(),
    method: "any".to_string(),
    occurrences: 3,
    receiver_shape: "Primitive()".to_string(),
    cause: "receiver is an untyped parameter of a lambda stored in a fold record field, the same shape as the object_store rows.".to_string(),
    dissolution: unbound_dissolution("lambda-parameter receiver typing from the declared fn type of the record field the lambda is stored in".to_string()),
}), Rc::new(UnresolvedMethodFrontierRow {
    module_name: "gunbc.scm_compatibility.mercurial".to_string(),
    method: "map".to_string(),
    occurrences: 3,
    receiver_shape: "Primitive()".to_string(),
    cause: "receiver is `missing_changesets`, an untyped parameter of the `partial:` lambda in a MercurialRepositoryCompletenessFold record field.".to_string(),
    dissolution: unbound_dissolution("lambda-parameter receiver typing from the declared fn type of the record field the lambda is stored in".to_string()),
}), Rc::new(UnresolvedMethodFrontierRow {
    module_name: "extdeps.dns.domain_name".to_string(),
    method: "list_push".to_string(),
    occurrences: 1,
    receiver_shape: "Primitive(ok)".to_string(),
    cause: "receiver is a coproduct payload bound by pattern destructuring, which arrives typed as the VARIANT name rather than the field type.".to_string(),
    dissolution: unbound_dissolution("coproduct payload binding typed as the field type, at which point the receiver is List and DECIDABLE".to_string()),
}), Rc::new(UnresolvedMethodFrontierRow {
    module_name: "v1.compiler.trace".to_string(),
    method: "map".to_string(),
    occurrences: 1,
    receiver_shape: "Product(SpanMapping)".to_string(),
    cause: "receiver is an Optional produced by `|> last`, and the optional functor is being mapped over. It arrives as the INNER product because the optional cardinality is dropped before method lookup, so Optional's own surface is never consulted.".to_string(),
    dissolution: unbound_dissolution("reconciling the two optionality representations (cardinality-marked node vs the nominal Optional coproduct) so an optional receiver keeps its optional surface at method lookup".to_string()),
}), Rc::new(UnresolvedMethodFrontierRow {
    module_name: "gunbc.source_integration_landing_spine".to_string(),
    method: "map".to_string(),
    occurrences: 1,
    receiver_shape: "Node(Optional)".to_string(),
    cause: "same optional-functor class as the v1.compiler.trace row, in its OTHER surface form: here the Optional survives as a named node rather than collapsing to its inner product, and neither form carries a method surface. Two shapes for one concept is itself the defect the trigger names.".to_string(),
    dissolution: unbound_dissolution("reconciling the two optionality representations so an optional receiver keeps its optional surface at method lookup".to_string()),
}), Rc::new(UnresolvedMethodFrontierRow {
    module_name: "test.claim.sccache_local_content_verified_on_read".to_string(),
    method: "contains".to_string(),
    occurrences: 1,
    receiver_shape: "Primitive(std.types.NonEmptyStr)".to_string(),
    cause: "the brand-alias class in its LEAF form. The receiver is a coproduct variant payload whose declared type is NonEmptyStr, and it arrives not as the refinement Conj the peel walks but as a plain leaf carrying the QUALIFIED name std.types.NonEmptyStr — so there is no refinement chain to descend and no kernel profile under that name. Three head-resolution strategies were tried against this site and measured: resolving the leaf through lookup_type_for, through lookup_type_by_name on the qualified name, and on its last segment. NONE of them recovered the refinement, so the machinery was deleted rather than shipped unproven, and the site is declared here instead. Why the peel reaches the Conj form but not this one is not yet understood, and saying so is more useful than a fourth guess.".to_string(),
    dissolution: unbound_dissolution("one representation for a brand alias at method lookup — the same reconciliation the conformance wall's class (2) names — so the leaf and Conj forms stop being two shapes for one concept".to_string()),
}), Rc::new(UnresolvedMethodFrontierRow {
    module_name: "v2.std.compilers.target_model".to_string(),
    method: "lookup".to_string(),
    occurrences: 1,
    receiver_shape: "Primitive(T)".to_string(),
    cause: "receiver is a bare type variable. This one is genuinely undecidable at this seam rather than a resolution defect: nothing establishes what T offers.".to_string(),
    dissolution: unbound_dissolution("primitive-realization-single-authority, giving every receiver a complete declared method surface".to_string()),
})])
}

pub fn frontier_diag_matches_row(
    d: Rc<CompilerDiagnostic>,
    method: String,
    receiver_shape: String,
) -> bool {
    match diagnostic_frontier_occurrence_key(d.clone()) {
        Some(key) => {
            ((key.method.clone() == method.clone())
                && (key.receiver_shape.clone() == receiver_shape.clone()))
        }
        None => false,
    }
}

pub fn frontier_row_observed(
    diagnostics: Rc<Vec<Rc<ErrorNode>>>,
    method: String,
    receiver_shape: String,
) -> Rc<Vec<Rc<ErrorNode>>> {
    Rc::new({
        let mut __result = Vec::new();
        for e in diagnostics.clone().iter().cloned() {
            if frontier_diag_matches_row(
                e.diagnostic.clone(),
                method.clone(),
                receiver_shape.clone(),
            ) {
                __result.push(e);
            }
        }
        __result
    })
}

pub fn frontier_row_budget_span(
    observed: Rc<Vec<Rc<ErrorNode>>>,
    module_span: Rc<SourceSpan>,
) -> Rc<SourceSpan> {
    match observed.clone().first().cloned() {
        Some(witness) => diagnostic_to_span(witness.diagnostic.clone()),
        None => module_span,
    }
}

pub fn frontier_row_budget_diags(
    row: Rc<UnresolvedMethodFrontierRow>,
    diagnostics: Rc<Vec<Rc<ErrorNode>>>,
    module_name: String,
    module_span: Rc<SourceSpan>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    if ((frontier_row_observed(
        diagnostics.clone(),
        row.method.clone(),
        row.receiver_shape.clone(),
    )
    .len() as i64)
        == row.occurrences.clone())
    {
        Rc::new(vec![])
    } else {
        Rc::new(vec![make_error_node(
            Rc::new(CompilerDiagnostic::FrontierOccurrenceBudgetExceeded {
                method: row.method.clone(),
                receiver_type: row.receiver_shape.clone(),
                declared: row.occurrences.clone(),
                observed: (frontier_row_observed(
                    diagnostics.clone(),
                    row.method.clone(),
                    row.receiver_shape.clone(),
                )
                .len() as i64),
                span: frontier_row_budget_span(
                    frontier_row_observed(
                        diagnostics.clone(),
                        row.method.clone(),
                        row.receiver_shape.clone(),
                    ),
                    module_span.clone(),
                ),
            }),
            module_name.clone(),
        )])
    }
}

pub fn frontier_occurrence_budget_diags(
    module_name: String,
    module_span: Rc<SourceSpan>,
    diagnostics: Rc<Vec<Rc<ErrorNode>>>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    Rc::new({
        let mut __result = Vec::new();
        for r in Rc::new({
            let mut __result = Vec::new();
            for r in unresolved_method_frontier().iter().cloned() {
                if (r.module_name.clone() == module_name.clone()) {
                    __result.push(r);
                }
            }
            __result
        })
        .iter()
        .cloned()
        {
            __result.extend(
                (*frontier_row_budget_diags(
                    r.clone(),
                    diagnostics.clone(),
                    module_name.clone(),
                    module_span.clone(),
                ))
                .iter()
                .cloned(),
            );
        }
        __result
    })
}

pub fn frontier_occurrence_budget_note() -> String {
    thread_local! {
        static CACHED: String = {
            "THE COUNT IS WHAT MAKES THE FRONTIER A RATCHET INSTEAD OF AN EXEMPTION. Keying admission on (module, method, receiver_shape) bounds WHERE an unresolved call may live but not HOW MANY may live there, so a second call in the same module, on the same method, failing to resolve the same way, inherited the admission — and that is not hypothetical: the measured rows are not all singletons (v2.compiler.tokenize admits seven `apply` calls, extdeps.mercurial three `any`, gunbc.scm_compatibility.mercurial three `map`), so a row admitting seven would silently admit an eighth (codex review 45464). Each row therefore declares its MEASURED occurrence count and this fold refuses the excess, located on the first offending call. THE COMPARISON IS EQUALITY, AND IT WAS FIRST WRITTEN AS A CEILING, WHICH DID NOT RATCHET. `observed > declared` was justified here on the reasoning that a narrower compile closure sees fewer occurrences of a module's rows, so equality would red a partial build. That reasoning is WRONG about this check: it runs per MODULE, and every occurrence of a module's rows is present whenever that module is typechecked at all — a closure that omits the module never runs its rows, so there is no partial-visibility case to protect. What the ceiling actually did was let seven shrink to six while the declared seven stood, so a seventh call could return silently: a static limit, not a ratchet, and the note claimed the ratchet anyway (codex review 45491). Equality closes it in the only way that works — fixing a call reds until the declared count is lowered, which removes the headroom a reintroduction would have slipped into. Both directions are asserted in the witness, because the under-count half is the half that makes it a ratchet and it is the one an author is tempted to relax. WHY NOT A STABLE PER-OCCURRENCE KEY, which would close this exactly: std.occurrence_identity is the corpus authority for occurrence identity and its own scope law forbids filename, SourceSpan, authored name, structural Node equality and content hash as identity inputs, allocating OccurrenceId inside one graph-scoped allocator instead. An allocator-assigned integer cannot appear as a literal in a declared row, because it is not stable across compiles — so a per-occurrence key is not merely unimplemented here, it is unavailable from the authority that owns the concept. The count is the strongest bound the substrate currently supports. Dissolve-on: a content-addressed occurrence identity stable across edits (the namespace lane's containment addressing), at which point rows key on the occurrence itself and the count field deletes.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn frontier_occurrence_budget_checked(
    module_name: String,
    module_span: Rc<SourceSpan>,
    diagnostics: Rc<Vec<Rc<ErrorNode>>>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    v1_rt::concat(
        diagnostics.clone(),
        frontier_occurrence_budget_diags(
            module_name.clone(),
            module_span.clone(),
            diagnostics.clone(),
        ),
    )
}

pub fn unresolved_method_frontier_trigger(
    module_name: String,
    method: String,
    receiver_shape: String,
) -> Option<Rc<DissolutionCondition>> {
    match Rc::new({
        let mut __result = Vec::new();
        for r in unresolved_method_frontier().iter().cloned() {
            if (((r.module_name.clone() == module_name.clone())
                && (r.method.clone() == method.clone()))
                && (r.receiver_shape.clone() == receiver_shape.clone()))
            {
                __result.push(r);
            }
        }
        __result
    })
    .first()
    .cloned()
    {
        Some(row) => Some(row.dissolution.clone()),
        None => None,
    }
}

pub fn unresolved_method_frontier_note() -> String {
    thread_local! {
        static CACHED: String = {
            "The declared frontier for method calls whose receiver establishes NO method surface even after where-refinement peeling (DESIGN §7: a declared row with a reason and a migration trigger, countable and prioritizable, never a silent escape hatch). WHY A ROSTER AT ALL: MethodExistenceUndecided BLOCKS. Leaving the undecided class non-blocking meant emittable_graph still emitted code containing a method whose existence was never established — the same fail-open the wall claims to close, correctly refused twice in review (codex reviews 45357 and 45383). Blocking it outright was not available either: the residue is CORRECT, WORKING code, seven sites of it the v2 tokenizer own LexMatchThunk { apply: fn(s) } idiom, so a blanket refusal would refuse the compiler v2 is migrating to — fabricating a refusal, which §5 forbids exactly as it forbids fabricating a success. THE KEY IS (module, method, receiver_shape), AND THE THIRD COMPONENT IS THE CORRECTION. A (module, method) key was shipped first and was wrong on two counts, one found by review and one by execution, which is worth recording because they are the same defect seen from two sides. Review found it as a fail-open: any NEW apply call in v2.compiler.tokenize would inherit the pass even on a fully resolved receiver, so the note claim that no new fail-open can enter was false (codex review 45398). Execution found it as an UNDERCOUNT: the roster was measured over the v1 self-compile closure alone, and the first whole-corpus run reded seven sites in three modules the roster had never seen. Both dissolve into the same fix — the frontier admits a receiver whose surface could not be established, so the SHAPE of that receiver is the evidence, and keying on it means a new call refuses unless it reproduces the exact unestablished shape the row was measured on. The residue after that is 13 sites in four shapes: Primitive() with no authored name (a lambda parameter whose type never propagates, 10 sites), Primitive(T) (a bare type variable), Primitive(ok) (a coproduct payload typed as its variant name), and a Product that is really an Optional whose cardinality was dropped. Every one is an upstream receiver-resolution defect, not a method-existence fact, which is exactly why the wall cannot decide them and why each row names the resolution fix rather than a permanent exemption. Admitted rows still emit MethodExistenceFrontierAdmitted, counted and carrying its own trigger, so the frequency stays observable rather than zeroed by construction (§5). THE RESIDUAL WIDENING, STATED RATHER THAN CLAIMED AWAY: a second unresolved call to the same method, in the same module, on a receiver that fails to resolve in the same way, is still admitted. That is narrower than the module-wide pass it replaces and it is not zero. Closing it entirely needs an occurrence identity stable across edits — content-addressed, not line-anchored — which is the same containment/content-hash authority the namespace lane is landing; until then the honest bound is this key, and the peel above is the mechanism that actually SHRINKS the frontier rather than administering it.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn categorized_error(
    message: String,
    span: Rc<SourceSpan>,
    module_name: String,
    category: String,
) -> Rc<ErrorNode> {
    make_error_node(
        Rc::new(CompilerDiagnostic::InternalError {
            message: message.clone(),
            span: span.clone(),
        }),
        module_name.clone(),
    )
}

pub fn validate_cast(
    source_inferred: Option<Rc<InferredNode>>,
    target_name: String,
    span: Rc<SourceSpan>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    module_name: String,
) -> Option<Rc<ErrorNode>> {
    match source_inferred.clone().as_deref().cloned() {
        Some(InferredNode::Resolved { node: src_node, .. }) => {
            let source_name = authored_name_at(source_indices.clone(), src_node.clone());
            if (source_name.clone() == target_name.clone()) {
                None
            } else {
                if !is_dag_cast_domain_type(source_name.clone()) {
                    None
                } else {
                    if !is_dag_cast_domain_type(target_name.clone()) {
                        None
                    } else {
                        if dag_can_cast(source_name.clone(), target_name.clone()) {
                            None
                        } else {
                            {
                                let msg = v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            "invalid cast: ".to_string(),
                                            source_name.clone(),
                                        ),
                                        " as ".to_string(),
                                    ),
                                    target_name.clone(),
                                );
                                let diag = Rc::new(CompilerDiagnostic::InternalError {
                                    message: msg.clone(),
                                    span: span.clone(),
                                });
                                Some(make_error_node(diag.clone(), module_name.clone()))
                            }
                        }
                    }
                }
            }
        }
        _ => None,
    }
}

pub fn optional_cast_diags(
    source_inferred: Option<Rc<InferredNode>>,
    target_type: Rc<Node>,
    span: Rc<SourceSpan>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    module_name: String,
) -> Rc<Vec<Rc<ErrorNode>>> {
    match source_inferred.clone().as_deref().cloned() {
        Some(InferredNode::Resolved { node: src_node, .. }) => {
            let source_name = authored_name_at(source_indices.clone(), src_node.clone());
            let source_is_optional = ((src_node.return_cardinality.clone()
                == Cardinality::CardOptional)
                || (qualified_last_segment(source_name.clone()) == "Optional".to_string()));
            let target_is_optional =
                (target_type.return_cardinality.clone() == Cardinality::CardOptional);
            if (source_is_optional.clone() && !target_is_optional.clone()) {
                Rc::new(vec![make_error_node(
                    Rc::new(CompilerDiagnostic::OptionalCastNotEliminated {
                        source_type: v1_rt::concat(source_name.clone(), "?".to_string()),
                        target_type: authored_name_at(source_indices.clone(), target_type.clone()),
                        span: span.clone(),
                    }),
                    module_name.clone(),
                )])
            } else {
                Rc::new(vec![])
            }
        }
        _ => Rc::new(vec![]),
    }
}

pub fn type_variable_node(id: String) -> Rc<Node> {
    Rc::new(Node {
        name: "".to_string(),
        span: no_span(),
        ident_span: None,
        children: Rc::new(vec![]),
        connective: Connective::NoConnective,
        params: Rc::new(vec![]),
        inferred: Some(Rc::new(InferredNode::TypeVariable { id: id.clone() })),
        return_cardinality: Cardinality::Required,
        uses: Rc::new(vec![]),
        body: None,
        transport: None,
        properties: Rc::new(vec![]),
        type_annotation: None,
        is_self_recursive: false,
        has_non_tail_self_call: false,
        match_pattern: None,
        expr_data: Rc::new(ExprData::NoExprData),
        ident: None,
    })
}

pub fn is_type_variable(inferred: Rc<InferredNode>) -> bool {
    match (*inferred.clone()).clone() {
        InferredNode::TypeVariable { id: _, .. } => true,
        _ => false,
    }
}

pub fn inferred_or_error(
    result: Option<Rc<InferredNode>>,
    fallback_message: String,
    fallback_span: Rc<SourceSpan>,
) -> Rc<InferredNode> {
    match result.clone() {
        Some(inferred) => inferred.clone(),
        None => Rc::new(InferredNode::CompilerError {
            message: fallback_message.clone(),
            span: fallback_span.clone(),
        }),
    }
}

pub fn resolve_pattern_subject(
    scope: Rc<InferScope>,
    scrutinee_subject: Rc<PatternSubject>,
) -> Rc<PatternSubject> {
    match (*scrutinee_subject.clone()).clone() {
        PatternSubject::PatternResolved {
            node: scrutinee_type,
            ..
        } => pattern_subject_from_node(preserve_outer_optional_cardinality(
            scrutinee_type.clone(),
            resolve_scrutinee_type_node(scope.type_env.clone(), scrutinee_type.clone()),
        )),
        PatternSubject::PatternDynamic {
            span: dynamic_span, ..
        } => Rc::new(PatternSubject::PatternDynamic {
            span: dynamic_span.clone(),
        }),
        PatternSubject::PatternLookupBlocked => Rc::new(PatternSubject::PatternLookupBlocked),
    }
}

pub fn annotate_pattern_parent_enums(
    pattern: Rc<MatchPattern>,
    scrutinee_subject: Rc<PatternSubject>,
    scope: Rc<InferScope>,
) -> Rc<MatchPattern> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*pattern.clone()).clone() {
            MatchPattern::VariantPattern {
                name: variant_name,
                field_bindings: bindings,
                ..
            } => {
                let resolved_scrut =
                    resolve_pattern_subject(scope.clone(), scrutinee_subject.clone());
                let inferred_parent = match (*resolved_scrut.clone()).clone() {
                    PatternSubject::PatternResolved {
                        node: resolved_scrut_node,
                        ..
                    } => {
                        let scrutinee_name = authored_name_at(
                            scope.type_env.clone().source_indices.clone(),
                            resolved_scrut_node.clone(),
                        );
                        let optional_cardinality_subject =
                            ((resolved_scrut_node.return_cardinality.clone()
                                == Cardinality::CardOptional)
                                && (scrutinee_name.clone() != "Optional".to_string()));
                        let optional_coproduct_subject = ((scrutinee_name.clone()
                            == "Optional".to_string())
                            && ((variant_name.clone() == "Present".to_string())
                                || (variant_name.clone() == "Absent".to_string())));
                        let witness_container_subject =
                            (is_witness_type_name(scrutinee_name.clone())
                                && ((variant_name.clone() == "Holds".to_string())
                                    || (variant_name.clone() == "Violates".to_string())));
                        if ((optional_cardinality_subject.clone()
                            || optional_coproduct_subject.clone())
                            && ((variant_name.clone() == "Present".to_string())
                                || (variant_name.clone() == "Absent".to_string())))
                        {
                            Some("Optional".to_string())
                        } else {
                            if witness_container_subject.clone() {
                                Some("Witness".to_string())
                            } else {
                                {
                                    let is_coproduct = (resolved_scrut_node.connective.clone()
                                        == Connective::Disj);
                                    if is_coproduct.clone() {
                                        Some(scrutinee_name.clone())
                                    } else {
                                        None
                                    }
                                }
                            }
                        }
                    }
                    PatternSubject::PatternDynamic { span: _, .. } => None,
                    PatternSubject::PatternLookupBlocked => None,
                };
                let annotated_variant_name = variant_name.clone();
                let variant_lookup = lookup_variant_in_type(
                    resolved_scrut.clone(),
                    variant_name.clone(),
                    scope.module_name.clone(),
                    scope.type_env.clone(),
                    (bindings.clone().len() as i64),
                );
                let variant_subject = lookup_result_subject(variant_lookup.clone());
                let annotated_bindings = Rc::new({
                    let mut __result = Vec::new();
                    for binding in bindings.clone().iter().cloned() {
                        __result.push({
                            let field_lookup = lookup_field_in_variant(
                                variant_subject.clone(),
                                field_binding_name_at(
                                    binding.clone(),
                                    scope.type_env.clone().source_indices.clone(),
                                ),
                                scope.module_name.clone(),
                                scope.type_env.clone().source_indices.clone(),
                            );
                            let field_subject = lookup_result_subject(field_lookup.clone());
                            make_field_binding_node(
                                field_binding_name_at(
                                    binding.clone(),
                                    scope.type_env.clone().source_indices.clone(),
                                ),
                                annotate_pattern_parent_enums(
                                    field_binding_pattern(binding.clone()),
                                    field_subject.clone(),
                                    scope.clone(),
                                ),
                                binding.span.clone(),
                                node_name_span(binding.clone()),
                            )
                        });
                    }
                    __result
                });
                match inferred_parent.clone() {
                    Some(parent_name) => Rc::new(MatchPattern::VariantPattern {
                        name: annotated_variant_name.clone(),
                        parent_enum: Some(parent_name.clone()),
                        field_bindings: annotated_bindings.clone(),
                    }),
                    None => Rc::new(MatchPattern::VariantPattern {
                        name: variant_name.clone(),
                        parent_enum: None,
                        field_bindings: annotated_bindings.clone(),
                    }),
                }
            }
            _ => pattern.clone(),
        }
    })
}

pub fn build_params_scope(scope: Rc<InferScope>, params: Rc<Vec<Rc<Node>>>) -> Rc<InferScope> {
    {
        let new_locals = params.clone().iter().cloned().fold(
            scope.locals.clone(),
            |acc: Rc<HashMap<String, Rc<TypeBinding>>>, p: Rc<Node>| {
                v1_rt::rc_map_insert(
                    acc,
                    param_node_name_at(p.clone(), scope.type_env.clone().source_indices.clone()),
                    Rc::new(TypeBinding {
                        name: param_node_name_at(
                            p.clone(),
                            scope.type_env.clone().source_indices.clone(),
                        ),
                        resolved: param_node_type_expr(p.clone()),
                        provenance: Rc::new(SubValueRelation::PreservedValue),
                    }),
                )
            },
        );
        let new_body_locals = params.clone().iter().cloned().fold(
            scope.body_locals.clone(),
            |acc: Rc<HashMap<String, bool>>, p: Rc<Node>| {
                v1_rt::rc_map_insert(
                    acc,
                    param_node_name_at(p.clone(), scope.type_env.clone().source_indices.clone()),
                    true,
                )
            },
        );
        Rc::new(InferScope {
            type_env: scope.type_env.clone(),
            func_env: scope.func_env.clone(),
            locals: new_locals.clone(),
            body_locals: new_body_locals.clone(),
            match_bound_names: scope.match_bound_names.clone(),
            module_name: scope.module_name.clone(),
            service_registry: scope.service_registry.clone(),
            item_registry: scope.item_registry.clone(),
            caller_decl_name: scope.caller_decl_name.clone(),
            lambda_param_provenance: v1_rt::rc_empty_map::<String, Rc<SubValueRelation>>(),
        })
    }
}

pub fn extend_scope(
    scope: Rc<InferScope>,
    name: String,
    resolved: Rc<Node>,
    provenance: Rc<SubValueRelation>,
) -> Rc<InferScope> {
    Rc::new(InferScope {
        type_env: scope.type_env.clone(),
        func_env: scope.func_env.clone(),
        locals: v1_rt::rc_map_insert(
            scope.locals.clone(),
            name.clone(),
            Rc::new(TypeBinding {
                name: name.clone(),
                resolved: resolved.clone(),
                provenance: provenance.clone(),
            }),
        ),
        body_locals: v1_rt::rc_map_insert(scope.body_locals.clone(), name.clone(), true),
        match_bound_names: scope.match_bound_names.clone(),
        module_name: scope.module_name.clone(),
        service_registry: scope.service_registry.clone(),
        item_registry: scope.item_registry.clone(),
        caller_decl_name: scope.caller_decl_name.clone(),
        lambda_param_provenance: scope.lambda_param_provenance.clone(),
    })
}

