pub fn symbol_index_insert_unique_disj_variant_aliases(
    index: Rc<SymbolIndex>,
    module_path: String,
    items: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    corpus_variant_counts: Rc<HashMap<String, i64>>,
    corpus_item_counts: Rc<HashMap<String, i64>>,
) -> Rc<SymbolIndex> {
    {
        let counts = disj_variant_name_counts(items.clone(), source_indices.clone());
        items
            .clone()
            .iter()
            .cloned()
            .fold(
                index.clone(),
                |acc: Rc<SymbolIndex>, item: Rc<Node>| match item.connective.clone() {
                    Connective::Disj => {
                        let tname = authored_name_at(source_indices.clone(), item.clone());
                        item.children.clone().iter().cloned().fold(
                            acc.clone(),
                            |a2: Rc<SymbolIndex>, child: Rc<Node>| {
                                let vname = authored_name_at(source_indices.clone(), child.clone());
                                let a2_qualified = symbol_index_insert(
                                    a2,
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(module_path.clone(), ".".to_string()),
                                                tname.clone(),
                                            ),
                                            ".".to_string(),
                                        ),
                                        vname.clone(),
                                    ),
                                    item.clone(),
                                );
                                match v1_rt::map_get(&counts, vname.clone()) {
                                    Some(1) => {
                                        match v1_rt::map_get(&corpus_variant_counts, vname.clone())
                                        {
                                            Some(1) => {
                                                if ((v1_rt::map_get(
                                                    &corpus_item_counts,
                                                    vname.clone(),
                                                ) != None)
                                                    || overlay_skips_kernel_name(vname.clone()))
                                                {
                                                    symbol_index_insert(
                                                        a2_qualified.clone(),
                                                        v1_rt::concat(
                                                            v1_rt::concat(
                                                                module_path.clone(),
                                                                ".".to_string(),
                                                            ),
                                                            vname.clone(),
                                                        ),
                                                        item.clone(),
                                                    )
                                                } else {
                                                    symbol_index_insert_decl(
                                                        a2_qualified.clone(),
                                                        module_path.clone(),
                                                        Rc::new(TypeBinding {
                                                            name: vname.clone(),
                                                            resolved: item.clone(),
                                                            provenance: Rc::new(
                                                                SubValueRelation::SubValueUnknown,
                                                            ),
                                                        }),
                                                    )
                                                }
                                            }
                                            _ => symbol_index_insert(
                                                a2_qualified.clone(),
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        module_path.clone(),
                                                        ".".to_string(),
                                                    ),
                                                    vname.clone(),
                                                ),
                                                item.clone(),
                                            ),
                                        }
                                    }
                                    _ => a2_qualified.clone(),
                                }
                            },
                        )
                    }
                    _ => acc.clone(),
                },
            )
    }
}

pub fn transparent_alias_target_name(
    item: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        let item_shape_admits = ((((((item.params.clone().len() as i64) == 0)
            && (item.connective.clone() == Connective::NoConnective))
            && ((item.children.clone().len() as i64) == 0))
            && ((item.properties.clone().len() as i64) == 0))
            && (item.type_annotation.clone() == None));
        if !item_shape_admits.clone() {
            "".to_string()
        } else {
            match item.inferred.clone().as_deref().cloned() {
                Some(InferredNode::Resolved { node: target, .. }) => {
                    let self_name = authored_name_at(source_indices.clone(), item.clone());
                    let target_name = authored_name_at(source_indices.clone(), target.clone());
                    let target_shape_admits = (((((target.connective.clone()
                        == Connective::NoConnective)
                        && ((target.children.clone().len() as i64) == 0))
                        && ((target.params.clone().len() as i64) == 0))
                        && (target.type_annotation.clone() == None))
                        && (target.return_cardinality.clone() == Cardinality::Required));
                    if !target_shape_admits.clone() {
                        "".to_string()
                    } else {
                        if ((target_name.clone() == "".to_string())
                            || (target_name.clone() == self_name.clone()))
                        {
                            "".to_string()
                        } else {
                            if (is_declared_container_alias_spelling(target_name.clone())
                                || is_container_type(qualified_last_segment(target_name.clone())))
                            {
                                "".to_string()
                            } else {
                                target_name.clone()
                            }
                        }
                    }
                }
                _ => "".to_string(),
            }
        }
    }
}

pub fn corpus_decl_module_paths(
    module_nodes: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    item_counts: Rc<HashMap<String, i64>>,
) -> Rc<HashMap<String, String>> {
    module_nodes.clone().iter().cloned().fold(
        v1_rt::rc_empty_map::<String, String>(),
        |acc: Rc<HashMap<String, String>>, module_node: Rc<Node>| {
            let module_path = authored_name_at(source_indices.clone(), module_node.clone());
            module_items(module_node.clone()).iter().cloned().fold(
                acc,
                |inner: Rc<HashMap<String, String>>, item: Rc<Node>| {
                    let self_name = authored_name_at(source_indices.clone(), item.clone());
                    let unique = match v1_rt::map_get(&item_counts, self_name.clone()) {
                        Some(1) => true,
                        _ => false,
                    };
                    if (((self_name.clone() == "".to_string())
                        || (module_path.clone() == "".to_string()))
                        || !unique.clone())
                    {
                        inner.clone()
                    } else {
                        v1_rt::rc_map_insert(inner.clone(), self_name.clone(), module_path.clone())
                    }
                },
            )
        },
    )
}

pub fn transparent_alias_qualified_name(
    decl_modules: Rc<HashMap<String, String>>,
    name: String,
) -> String {
    if ((module_path_segments(name.clone()).len() as i64) > 1) {
        name.clone()
    } else {
        match v1_rt::map_get(&decl_modules, name.clone()) {
            Some(m) => v1_rt::concat(v1_rt::concat(m.clone(), ".".to_string()), name.clone()),
            None => name.clone(),
        }
    }
}

pub fn transparent_alias_direct_edges(
    module_nodes: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    item_counts: Rc<HashMap<String, i64>>,
    decl_modules: Rc<HashMap<String, String>>,
) -> Rc<HashMap<String, String>> {
    module_nodes.clone().iter().cloned().fold(
        v1_rt::rc_empty_map::<String, String>(),
        |edges: Rc<HashMap<String, String>>, module_node: Rc<Node>| {
            let module_path = authored_name_at(source_indices.clone(), module_node.clone());
            module_items(module_node.clone()).iter().cloned().fold(
                edges,
                |acc: Rc<HashMap<String, String>>, item: Rc<Node>| {
                    let raw_target =
                        transparent_alias_target_name(item.clone(), source_indices.clone());
                    if (raw_target.clone() == "".to_string()) {
                        acc.clone()
                    } else {
                        {
                            let target_name = transparent_alias_qualified_name(
                                decl_modules.clone(),
                                raw_target.clone(),
                            );
                            let self_name = authored_name_at(source_indices.clone(), item.clone());
                            let qualified = v1_rt::rc_map_insert(
                                acc.clone(),
                                v1_rt::concat(
                                    v1_rt::concat(module_path.clone(), ".".to_string()),
                                    self_name.clone(),
                                ),
                                target_name.clone(),
                            );
                            match v1_rt::map_get(&item_counts, self_name.clone()) {
                                Some(1) => v1_rt::rc_map_insert(
                                    qualified.clone(),
                                    self_name.clone(),
                                    target_name.clone(),
                                ),
                                _ => qualified.clone(),
                            }
                        }
                    }
                },
            )
        },
    )
}

pub fn transparent_alias_chase(
    mut edges: Rc<HashMap<String, String>>,
    mut name: String,
    mut fuel: i64,
) -> String {
    loop {
        if (fuel.clone() <= 0) {
            break name.clone();
        } else {
            match v1_rt::map_get(&edges, name.clone()) {
                Some(next) => {
                    if (next.clone() == name.clone()) {
                        break name.clone();
                    } else {
                        {
                            let __tco_0 = next.clone();
                            let __tco_1 = (fuel - 1);
                            name = __tco_0;
                            fuel = __tco_1;
                            continue;
                        }
                    }
                }
                None => match v1_rt::map_get(&edges, qualified_last_segment(name.clone())) {
                    Some(next) => {
                        if ((next.clone() == name.clone())
                            || (qualified_last_segment(next.clone())
                                == qualified_last_segment(name.clone())))
                        {
                            break name.clone();
                        } else {
                            {
                                let __tco_0 = next.clone();
                                let __tco_1 = (fuel - 1);
                                name = __tco_0;
                                fuel = __tco_1;
                                continue;
                            }
                        }
                    }
                    None => {
                        break name.clone();
                    }
                },
            }
        }
    }
}

pub fn transparent_alias_representatives(
    module_nodes: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    item_counts: Rc<HashMap<String, i64>>,
) -> Rc<HashMap<String, String>> {
    {
        let decl_modules = corpus_decl_module_paths(
            module_nodes.clone(),
            source_indices.clone(),
            item_counts.clone(),
        );
        let edges = transparent_alias_direct_edges(
            module_nodes.clone(),
            source_indices.clone(),
            item_counts.clone(),
            decl_modules.clone(),
        );
        Rc::new(v1_rt::sorted_map_keys(&edges))
            .iter()
            .cloned()
            .fold(
                v1_rt::rc_empty_map::<String, String>(),
                |acc: Rc<HashMap<String, String>>, k: String| {
                    v1_rt::rc_map_insert(
                        acc,
                        k.clone(),
                        transparent_alias_chase(edges.clone(), k.clone(), 16),
                    )
                },
            )
    }
}

pub fn transparent_alias_representative(index: Rc<SymbolIndex>, name: String) -> String {
    match v1_rt::map_get(&index.transparent_alias_rep.clone(), name.clone()) {
        Some(rep) => rep.clone(),
        None => match v1_rt::map_get(
            &index.transparent_alias_rep.clone(),
            qualified_last_segment(name.clone()),
        ) {
            Some(rep) => rep.clone(),
            None => name.clone(),
        },
    }
}

pub fn transparent_alias_identity_agrees(
    index: Rc<SymbolIndex>,
    left: String,
    right: String,
) -> bool {
    {
        let left_rep = transparent_alias_representative(index.clone(), left.clone());
        let right_rep = transparent_alias_representative(index.clone(), right.clone());
        let left_chased = (left_rep.clone() != left.clone());
        let right_chased = (right_rep.clone() != right.clone());
        let both_chased = (left_chased.clone() && right_chased.clone());
        ((((left.clone() != "".to_string()) && (right.clone() != "".to_string()))
            && (left_chased.clone() || right_chased.clone()))
            && if both_chased.clone() {
                (left_rep.clone() == right_rep.clone())
            } else {
                (qualified_last_segment(left_rep.clone())
                    == qualified_last_segment(right_rep.clone()))
            })
    }
}

pub fn build_symbol_index_census_raw_nodes(
    module_nodes: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<SymbolIndex> {
    {
        let corpus_variant_counts =
            corpus_disj_variant_name_counts_nodes(module_nodes.clone(), source_indices.clone());
        let corpus_item_counts =
            corpus_item_name_counts_nodes(module_nodes.clone(), source_indices.clone());
        let folded = module_nodes.clone().iter().cloned().fold(
            empty_symbol_index(),
            |index: Rc<SymbolIndex>, module_node: Rc<Node>| {
                let module_path = authored_name_at(source_indices.clone(), module_node.clone());
                let items = module_items(module_node.clone());
                let with_items = items.clone().iter().cloned().fold(
                    index,
                    |acc: Rc<SymbolIndex>, item: Rc<Node>| {
                        symbol_index_insert_item(
                            acc,
                            module_path.clone(),
                            item.clone(),
                            source_indices.clone(),
                        )
                    },
                );
                symbol_index_insert_unique_disj_variant_aliases(
                    with_items.clone(),
                    module_path.clone(),
                    items.clone(),
                    source_indices.clone(),
                    corpus_variant_counts.clone(),
                    corpus_item_counts.clone(),
                )
            },
        );
        Rc::new(SymbolIndex {
            entries: folded.entries.clone(),
            global_bare: folded.global_bare.clone(),
            services: folded.services.clone(),
            transparent_alias_rep: transparent_alias_representatives(
                module_nodes.clone(),
                source_indices.clone(),
                corpus_item_counts.clone(),
            ),
        })
    }
}

pub fn build_symbol_index_census_raw(
    modules: Rc<Vec<Rc<ResolvedModule>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<SymbolIndex> {
    build_symbol_index_census_raw_nodes(
        census_module_nodes(modules.clone()),
        source_indices.clone(),
    )
}

pub fn census_borrowed_sig_resolution_note() -> String {
    thread_local! {
        static CACHED: String = {
            "Borrowed-sig hoist (namespace lane): the census stores raw pre-typecheck fn nodes, so a borrowed generic fn's return leaked bare type-param leaves (T/V/E) and owner-local names into consumers — the local/borrowed asymmetry (locals resolve once per module in resolve_item_types with type params bound as TypeVariables; borrows got the raw node per lookup). Pass 2 resolves each borrowable GENERIC fn signature's return ONCE at census build, in a synthetic env at the OWNER's containment position (module_path = the candidate's declaring module; symbol_index = the completed pass-1 census; type params bound via env_with_type_variable_bindings) — order-independent (resolution reads only the completed raw census, never a partial one), once per decl (never per lookup — the per-lookup variant re-resolved recursive carriers to the depth bound on every call), and staged fail-closed: ANY resolution diagnostic keeps the raw binding, so the consumer-side refusal surface is unchanged (upgraded | raw is a typed frontier, not a widen). Scope: fn sigs with value params (params non-empty; type params may be zero — a NON-generic fn's return can still USE a generic type, e.g. Outcome<Medium<String>>, and needs the same owner-position expansion for variant-payload substitution); 0-arg fns and aliases share a census shape (body stripped) and stay raw pending a discriminator.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn census_fn_sig_env(
    census: Rc<SymbolIndex>,
    module_path: String,
    tp_names: Rc<Vec<String>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<TypeEnv> {
    {
        let base = Rc::new(TypeEnv {
            module_path: module_path.clone(),
            bindings: v1_rt::rc_empty_map::<i64, Rc<TypeBinding>>(),
            str_bindings: v1_rt::rc_empty_map::<String, Rc<TypeBinding>>(),
            ancestry_str_bindings: v1_rt::rc_empty_map::<String, Rc<TypeBinding>>(),
            parents: Rc::new(vec![]),
            recursive_types: Rc::new(vec![]),
            recursive_type_set: v1_rt::rc_empty_map::<i64, bool>(),
            inductive_fields: v1_rt::rc_empty_map::<String, Rc<Vec<Rc<InductiveField>>>>(),
            source_indices: source_indices.clone(),
            intern_table: empty_intern_table(),
            source_visible_names: v1_rt::rc_empty_map::<String, bool>(),
            symbol_index: census.clone(),
        });
        env_with_type_variable_bindings(base.clone(), tp_names.clone())
    }
}

pub fn census_binding_is_borrowable_fn_sig(
    binding: Rc<TypeBinding>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let node = binding.resolved.clone();
        ((((((node.connective.clone() == Connective::NoConnective)
            && ((node.children.clone().len() as i64) == 0))
            && (node.body.clone() == None))
            && (node.transport.clone() == None))
            && (node.inferred.clone() != None))
            && ((node.params.clone().len() as i64) > 0))
    }
}

pub fn census_qualify_sig_return_binding(
    binding: Rc<TypeBinding>,
    module_path: String,
    census: Rc<SymbolIndex>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<TypeBinding> {
    {
        let node = binding.resolved.clone();
        let env = census_fn_sig_env(
            census.clone(),
            module_path.clone(),
            Rc::new(vec![]),
            source_indices.clone(),
        );
        Rc::new(TypeBinding {
            name: binding.name.clone(),
            resolved: node_with_inferred(
                node.clone(),
                qualify_borrowed_inferred(
                    node.inferred.clone(),
                    module_path.clone(),
                    env.clone(),
                    v1_rt::rc_empty_map::<String, bool>(),
                ),
            ),
            provenance: binding.provenance.clone(),
        })
    }
}

pub fn census_upgrade_sig_binding(
    binding: Rc<TypeBinding>,
    module_path: String,
    census: Rc<SymbolIndex>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    tp_names: Rc<Vec<String>>,
) -> Rc<TypeBinding> {
    if ((tp_names.clone().len() as i64) > 0) {
        {
            let node = binding.resolved.clone();
            match node.inferred.clone().as_deref().cloned() {
                Some(InferredNode::Resolved { node: raw_ret, .. }) => {
                    let env = census_fn_sig_env(
                        census.clone(),
                        module_path.clone(),
                        tp_names.clone(),
                        source_indices.clone(),
                    );
                    let ret_result =
                        resolve_node(raw_ret.clone(), env.clone(), module_path.clone());
                    if ((ret_result.diagnostics.clone().len() as i64) == 0) {
                        {
                            let preserved = preserve_nominal_brand_on_resolve(
                                raw_ret.clone(),
                                ret_result.resolved.clone(),
                                authored_name_at(source_indices.clone(), raw_ret.clone()),
                                source_indices.clone(),
                            );
                            Rc::new(TypeBinding {
                                name: binding.name.clone(),
                                resolved: node_with_inferred(
                                    node.clone(),
                                    Some(Rc::new(InferredNode::Resolved {
                                        node: preserved.clone(),
                                    })),
                                ),
                                provenance: binding.provenance.clone(),
                            })
                        }
                    } else {
                        binding.clone()
                    }
                }
                _ => binding.clone(),
            }
        }
    } else {
        binding.clone()
    }
}

pub fn stamp_field_type_from_decl_params(
    field_type: Rc<Node>,
    serving_decl: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Node> {
    if (((serving_decl.params.clone().len() as i64) == 0) || (field_type.inferred.clone() != None))
    {
        field_type.clone()
    } else {
        {
            let is_bare = ((((field_type.children.clone().len() as i64) == 0)
                && (field_type.connective.clone() == Connective::NoConnective))
                && ((field_type.params.clone().len() as i64) == 0));
            if is_bare.clone() {
                {
                    let nm = type_node_label(field_type.clone(), source_indices.clone());
                    let is_param = Rc::new({
                        let mut __result = Vec::new();
                        for p in serving_decl.params.clone().iter().cloned() {
                            __result.push(generic_param_name_at(p.clone(), source_indices.clone()));
                        }
                        __result
                    })
                    .iter()
                    .cloned()
                    .fold(false, |acc: bool, pn: String| {
                        (acc || (pn.clone() == nm.clone()))
                    });
                    if is_param.clone() {
                        node_with_inferred(
                            field_type.clone(),
                            Some(Rc::new(InferredNode::TypeVariable { id: nm.clone() })),
                        )
                    } else {
                        field_type.clone()
                    }
                }
            } else {
                field_type.clone()
            }
        }
    }
}

pub fn stamp_type_param_occurrences(
    n: Rc<Node>,
    param_names: Rc<HashMap<String, bool>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Node> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let is_bare = ((((n.children.clone().len() as i64) == 0)
            && (n.connective.clone() == Connective::NoConnective))
            && ((n.params.clone().len() as i64) == 0));
        if is_bare.clone() {
            if (n.inferred.clone() == None) {
                {
                    let nm = type_node_label(n.clone(), source_indices.clone());
                    match v1_rt::map_get(&param_names, nm.clone()) {
                        Some(_) => node_with_inferred(
                            n.clone(),
                            Some(Rc::new(InferredNode::TypeVariable { id: nm.clone() })),
                        ),
                        _ => n.clone(),
                    }
                }
            } else {
                n.clone()
            }
        } else {
            node_with_children(
                n.clone(),
                Rc::new({
                    let mut __result = Vec::new();
                    for c in n.children.clone().iter().cloned() {
                        __result.push(stamp_type_param_occurrences(
                            c.clone(),
                            param_names.clone(),
                            source_indices.clone(),
                        ));
                    }
                    __result
                }),
            )
        }
    })
}

pub fn census_upgrade_type_decl_binding(
    binding: Rc<TypeBinding>,
    module_path: String,
    census: Rc<SymbolIndex>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<TypeBinding> {
    {
        let node = binding.resolved.clone();
        let param_names = Rc::new({
            let mut __result = Vec::new();
            for p in node.params.clone().iter().cloned() {
                __result.push(generic_param_name_at(p.clone(), source_indices.clone()));
            }
            __result
        });
        let excluded = param_names.clone().iter().cloned().fold(
            v1_rt::rc_map_insert(
                v1_rt::rc_empty_map::<String, bool>(),
                binding.name.clone(),
                true,
            ),
            |acc: Rc<HashMap<String, bool>>, nm: String| {
                v1_rt::rc_map_insert(acc, nm.clone(), true)
            },
        );
        let env = census_fn_sig_env(
            census.clone(),
            module_path.clone(),
            param_names.clone(),
            source_indices.clone(),
        );
        Rc::new(TypeBinding {
            name: binding.name.clone(),
            resolved: qualify_decl_reference_positions(
                node.clone(),
                module_path.clone(),
                env.clone(),
                excluded.clone(),
            ),
            provenance: binding.provenance.clone(),
        })
    }
}

